actory\\nimport android.graphics.Canvas\\nimport android.graphics.Color\\nimport android.graphics.Paint\\nimport android.graphics.Path\\nimport android.text.Editable\\nimport android.text.Spanned\\nimport android.text.TextWatcher\\nimport android.text.style.SuperscriptSpan\\nimport android.text.style.RelativeSizeSpan\\nimport android.text.style.ForegroundColorSpan\\nimport android.view.MotionEvent\\nimport android.view.ScaleGestureDetector\\nimport android.widget.Button\\nimport android.widget.EditText\\nimport android.widget.ImageView\\nimport androidx.appcompat.app.AppCompatActivity\\n\\nclass MathParser3D(private val expr: String) {\\n    private val expression = expr\\n        .replace(\\"\\u00b2\\", \\"^2\\")\\n        .replace(\\"\\u00b3\\", \\"^3\\")\\n        .replace(\\"\\u00b9\\", \\"^1\\")\\n        .replace(\\"\\u2074\\", \\"^4\\")\\n        .replace(\\"**\\", \\"^\\")\\n    private var pos = -1\\n    private var ch = 0\\n\\n    private fun nextChar() {\\n        pos++\\n        ch = if (pos < expression.length) expression[pos].code else -1\\n    }\\n\\n    private fun eat(charToEat: Int): Boolean {\\n        while (ch == ' '.code) nextChar()\\n        if (ch == charToEat) {\\n            nextChar()\\n            return true\\n        }\\n        return false\\n    }\\n\\n    fun parse(xVal: Double, yVal: Double): Double {\\n        return parse(xVal, yVal, 0.0)\\n    }\\n\\n    fun parse(xVal: Double, yVal: Double, zVal: Double): Double {\\n        pos = -1\\n        nextChar()\\n        return parseExpression(xVal, yVal, zVal)\\n    }\\n\\n    private fun parseExpression(xVal: Double, yVal: Double, zVal: Double): Double {\\n        var x = parseTerm(xVal, yVal, zVal)\\n        while (true) {\\n            if (eat('+'.code)) x += parseTerm(xVal, yVal, zVal)\\n            else if (eat('-'.code)) x -= parseTerm(xVal, yVal, zVal)\\n            else return x\\n        }\\n    }\\n\\n    private fun parseTerm(xVal: Double, yVal: Double, zVal: Double): Double {\\n        var x = parseFactor(xVal, yVal, zVal)\\n        while (true) {\\n            if (eat('*'.code)) x *= parseFactor(xVal, yVal, zVal)\\n            else if (eat('/'.code)) x /= parseFactor(xVal, yVal, zVal)\\n            else return x\\n        }\\n    }\\n\\n    private fun parseFactor(xVal: Double, yVal: Double, zVal: Double): Double {\\n        if (eat('+'.code)) return parseFactor(xVal, yVal, zVal)\\n        if (eat('-'.code)) return -parseFactor(xVal, yVal, zVal)\\n\\n        val startPos = this.pos\\n        var x = 0.0\\n\\n        if (eat('('.code)) {\\n            x = parseExpression(xVal, yVal, zVal)\\n            eat(')'.code)\\n        } else if ((ch >= '0'.code && ch <= '9'.code) || ch == '.'.code) {\\n            while ((ch >= '0'.code && ch <= '9'.code) || ch == '.'.code) nextChar()\\n            x = expression.substring(startPos, this.pos).toDoubleOrNull() ?: 0.0\\n        } else if ((ch >= 'a'.code && ch <= 'z'.code) || (ch >= 'A'.code && ch <= 'Z'.code)) {\\n            while ((ch >= 'a'.code && ch <= 'z'.code) || (ch >= 'A'.code && ch <= 'Z'.code)) nextChar()\\n            val func = expression.substring(startPos, this.pos).lowercase()\\n            if (func == \\"x\\" || func == \\"u\\") {\\n                x = xVal\\n            } else if (func == \\"y\\" || func == \\"v\\") {\\n                x = yVal\\n            } else if (func == \\"z\\") {\\n                x = zVal\\n            } else if (func == \\"and\\") {\\n                x = Math.E\\n            } else if (func == \\"pi\\") {\\n                x = Math.PI\\n            } else if (eat('('.code)) {\\n                val arg = parseExpression(xVal, yVal, zVal)\\n                eat(')'.code)\\n                x = when (func) {\\n                    \\"sin\\" -> Math.sin(arg)\\n                    \\"cos\\" -> Math.cos(arg)\\n                    \\"tan\\" -> Math.tan(arg)\\n                    \\"sqrt\\" -> Math.sqrt(arg)\\n                    \\"abs\\" -> Math.abs(arg)\\n                    \\"exp\\" -> Math.exp(arg)\\n                    \\"log\\", \\"ln\\" -> Math.log(arg)\\n                    else -> 0.0\\n                }\\n            }\\n        }\\n\\n        if (eat('^'.code)) x = Math.pow(x, parseFactor(xVal, yVal, zVal))\\n\\n        return x\\n    }\\n}\\n\\nprivate data class Point3D(val x: Double, val y: Double, val z: Double)\\nprivate data class Face3D(val p1: Point3D, val p2: Point3D, val p3: Point3D, val p4: Point3D)\\n\\nprivate data class Quad3D(\\n    val p1x: Float, val p1y: Float,\\n    val p2x: Float, val p2y: Float,\\n    val p3x: Float, val p3y: Float,\\n    val p4x: Float, val p4y: Float,\\n    val avgZ: Float,\\n    val rawZ: Float\\n)\\n\\nclass Grafico_3dActivity : AppCompatActivity() {\\n\\n    private var isUpdatingText = false\\n    \\n    private var rotX = 35f\\n    private var rotY = 45f\\n    private var lastTouchX = 0f\\n    private var lastTouchY = 0f\\n    \\n    private var globalScale = 55.0\\n    private lateinit var scaleDetector: ScaleGestureDetector\\n\\n    @SuppressLint(\\"ClickableViewAccessibility\\")\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContentView(R.layout.grafico_3d)\\n\\n        try {\\n            val logoView = findViewById<ImageView>(R.id.logo3)\\n            val inputStream = assets.open(\\"logo3.png\\")\\n            val bitmap = BitmapFactory.decodeStream(inputStream)\\n            logoView?.setImageBitmap(bitmap)\\n        } catch (and: Exception) {\\n            and.printStackTrace()\\n        }\\n\\n        val edtFuncao3D = findViewById<EditText>(R.id.edtFuncao3D)\\n        val btnGerarGrafico3D = findViewById<Button>(R.id.btnGerarGrafico3D)\\n        val imgGraficoCanvas3D = findViewById<ImageView>(R.id.imgGraficoCanvas3D)\\n\\n        edtFuncao3D?.addTextChangedListener(object : TextWatcher {\\n            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}\\n            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}\\n            override fun afterTextChanged(s: Editable?) {\\n                if (isUpdatingText || s == null) return\\n                isUpdatingText = true\\n\\n                try {\\n                    val spansSup = s.getSpans(0, s.length, SuperscriptSpan::class.java)\\n                    for (span in spansSup) s.removeSpan(span)\\n                    val spansSize = s.getSpans(0, s.length, RelativeSizeSpan::class.java)\\n                    for (span in spansSize) s.removeSpan(span)\\n                    val spansColor = s.getSpans(0, s.length, ForegroundColorSpan::class.java)\\n                    for (span in spansColor) s.removeSpan(span)\\n\\n                    val rawText = s.toString()\\n                    val pattern = Regex(\\"(\\\\\\\\*\\\\\\\\*|\\\\\\\\^)([0-9xXyYuUvVzZ]+)\\")\\n                    val matches = pattern.findAll(rawText)\\n\\n                    for (match in matches) {\\n                        val opRange = match.groups[1]?.range ?: continue\\n                        val expRange = match.groups[2]?.range ?: continue\\n\\n                        s.setSpan(ForegroundColorSpan(Color.TRANSPARENT), opRange.first, opRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                        s.setSpan(RelativeSizeSpan(0.0f), opRange.first, opRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n\\n                        s.setSpan(SuperscriptSpan(), expRange.first, expRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                        s.setSpan(RelativeSizeSpan(0.75f), expRange.first, expRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                    }\\n                } catch (and: Exception) {\\n                    and.printStackTrace()\\n                }\\n\\n                isUpdatingText = false\\n            }\\n        })\\n\\n        scaleDetector = ScaleGestureDetector(this, object : ScaleGestureDetector.SimpleOnScaleGestureListener() {\\n            override fun onScale(detector: ScaleGestureDetector): Boolean {\\n                globalScale *= detector.scaleFactor\\n                globalScale = globalScale.coerceIn(10.0, 300.0) \\n\\n                val expressao = edtFuncao3D?.text?.toString() ?: \\"sphere\\"\\n                imgGraficoCanvas3D?.setImageBitmap(desenharSuperficie3D(expressao))\\n                return true\\n            }\\n        })\\n\\n        imgGraficoCanvas3D?.setOnTouchListener { _, event ->\\n            scaleDetector.onTouchEvent(event)\\n\\n            if (!scaleDetector.isInProgress) {\\n                when (event.action) {\\n                    MotionEvent.ACTION_DOWN -> {\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                    MotionEvent.ACTION_MOVE -> {\\n                        val dx = event.x - lastTouchX\\n                        val dy = event.y - lastTouchY\\n                        \\n                        rotY -= dx * 0.4f\\n                        rotX -= dy * 0.4f\\n                        \\n                        rotX = rotX.coerceIn(-85f, 85f)\\n\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n\\n                        val expressao = edtFuncao3D?.text?.toString() ?: \\"sphere\\"\\n                        imgGraficoCanvas3D.setImageBitmap(desenharSuperficie3D(expressao))\\n                    }\\n                }\\n            }\\n            true\\n        }\\n\\n        btnGerarGrafico3D?.setOnClickListener {\\n            rotX = 35f\\n            rotY = 45f\\n            globalScale = 55.0\\n            val expressao = edtFuncao3D?.text?.toString() ?: \\"sphere\\"\\n            val bitmapGrafico = desenharSuperficie3D(expressao)\\n            imgGraficoCanvas3D?.setImageBitmap(bitmapGrafico)\\n        }\\n\\n        val bitmapInicial = desenharSuperficie3D(\\"sphere\\")\\n        imgGraficoCanvas3D?.setImageBitmap(bitmapInicial)\\n    }\\n\\n    private fun desenharSuperficie3D(expressao: String): Bitmap {\\n        val width = 900\\n        val height = 900\\n        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n\\n        val gridSize = 40\\n        val exprClean = expressao.lowercase().trim()\\n\\n        var minZ = Double.MAX_VALUE\\n        var maxZ = -Double.MAX_VALUE\\n\\n        val scale = globalScale \\n        val centerX = width / 2.0\\n        val centerY = height / 2.0 + 40.0\\n\\n        fun project(x: Double, y: Double, z: Double): Triple<Float, Float, Float> {\\n            val rZ = Math.toRadians(rotY.toDouble())\\n            val cosZ = Math.cos(rZ)\\n            val sinZ = Math.sin(rZ)\\n            \\n            val x1 = x * cosZ - y * sinZ\\n            val y1 = x * sinZ + y * cosZ\\n            \\n            val rX = Math.toRadians(rotX.toDouble())\\n            val cosX = Math.cos(rX)\\n            val sinX = Math.sin(rX)\\n            \\n            val projY = y1 * cosX - z * sinX\\n            val depth = y1 * sinX + z * cosX \\n\\n            val px = (centerX + x1 * scale).toFloat()\\n            val py = (centerY - projY * scale).toFloat() \\n            return Triple(px, py, depth.toFloat())\\n        }\\n\\n        val paintAxisX = Paint().apply { color = Color.parseColor(\\"#EF4444\\"); strokeWidth = 3f; isAntiAlias = true }\\n        val paintAxisY = Paint().apply { color = Color.parseColor(\\"#10B981\\"); strokeWidth = 3f; isAntiAlias = true }\\n        val paintAxisZ = Paint().apply { color = Color.parseColor(\\"#3B82F6\\"); strokeWidth = 3.5f; isAntiAlias = true }\\n        val paintGridPlane = Paint().apply { color = Color.parseColor(\\"#64748B\\"); strokeWidth = 1.5f; style = Paint.Style.STROKE; isAntiAlias = true }\\n        val paintAxisText = Paint().apply { color = Color.parseColor(\\"#1E293B\\"); textSize = 20f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n\\n        val regexPontos3D = Regex(\\"\\\\\\\\(\\\\\\\\s*(-?\\\\\\\\d+\\\\\\\\.?\\\\\\\\d*)\\\\\\\\s*,\\\\\\\\s*(-?\\\\\\\\d+\\\\\\\\.?\\\\\\\\d*)\\\\\\\\s*,\\\\\\\\s*(-?\\\\\\\\d+\\\\\\\\.?\\\\\\\\d*)\\\\\\\\s*\\\\\\\\)\\")\\n        val matches3D = regexPontos3D.findAll(exprClean).toList()\\n\\n        if (matches3D.isNotEmpty()) {\\n            val path3D = Path()\\n            var primeiroPonto = true\\n            val paintPonto3D = Paint().apply { color = Color.parseColor(\\"#DC2626\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n            val paintPoligono3D = Paint().apply { color = Color.parseColor(\\"#443B82F6\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n            val paintAresta3D = Paint().apply { color = Color.parseColor(\\"#1E293B\\"); strokeWidth = 4f; style = Paint.Style.STROKE; strokeJoin = Paint.Join.ROUND; isAntiAlias = true }\\n\\n            minZ = -5.0\\n            maxZ = 5.0\\n            val floorZ = minZ - 1.2\\n            val gridSteps = 8\\n\\n            for (i in 0..gridSteps) {\\n                val currVal = -5.0 + i * (10.0 / gridSteps)\\n                val pStart = project(currVal, -5.0, floorZ)\\n                val pEnd = project(currVal, 5.0, floorZ)\\n                canvas.drawLine(pStart.first, pStart.second, pEnd.first, pEnd.second, paintGridPlane)\\n\\n                val pStart2 = project(-5.0, currVal, floorZ)\\n                val pEnd2 = project(5.0, currVal, floorZ)\\n                canvas.drawLine(pStart2.first, pStart2.second, pEnd2.first, pEnd2.second, paintGridPlane)\\n            }\\n\\n            val originBottom = project(0.0, 0.0, floorZ)\\n            val originTop = project(0.0, 0.0, maxZ + 1.5)\\n            canvas.drawLine(originBottom.first, originBottom.second, originTop.first, originTop.second, paintAxisZ)\\n\\n            val xAxisStart = project(-5.0, 0.0, floorZ)\\n            val xAxisEnd = project(5.0, 0.0, floorZ)\\n            canvas.drawLine(xAxisStart.first, xAxisStart.second, xAxisEnd.first, xAxisEnd.second, paintAxisX)\\n\\n            val yAxisStart = project(0.0, -5.0, floorZ)\\n            val yAxisEnd = project(0.0, 5.0, floorZ)\\n            canvas.drawLine(yAxisStart.first, yAxisStart.second, yAxisEnd.first, yAxisEnd.second, paintAxisY)\\n\\n            for ((index, match) in matches3D.withIndex()) {\\n                val x = match.groupValues[1].toDouble()\\n                val y = match.groupValues[2].toDouble()\\n                val z = match.groupValues[3].toDouble()\\n\\n                val projecao = project(x, y, z)\\n\\n                if (primeiroPonto) {\\n                    path3D.moveTo(projecao.first, projecao.second)\\n                    primeiroPonto = false\\n                } else {\\n                    path3D.lineTo(projecao.first, projecao.second)\\n                }\\n\\n                canvas.drawCircle(projecao.first, projecao.second, 8f, paintPonto3D)\\n                canvas.drawText(String.format(\\"%c\\", 'A'.code + (index % 26)), projecao.first + 18f, projecao.second - 10f, paintAxisText)\\n            }\\n\\n            if (matches3D.size > 2) {\\n                path3D.close()\\n                canvas.drawPath(path3D, paintPoligono3D)\\n            }\\n            canvas.drawPath(path3D, paintAresta3D)\\n\\n            return bitmap\\n        }\\n\\n        val rawFaces = mutableListOf<Face3D>()\\n\\n        if (exprClean == \\"cubo\\") {\\n            val s = 3.0\\n            val p0 = Point3D(-s, -s, -s); val p1 = Point3D(s, -s, -s); val p2 = Point3D(s, s, -s); val p3 = Point3D(-s, s, -s)\\n            val p4 = Point3D(-s, -s, s); val p5 = Point3D(s, -s, s); val p6 = Point3D(s, s, s); val p7 = Point3D(-s, s, s)\\n            \\n            rawFaces.add(Face3D(p0, p1, p2, p3)) \\n            rawFaces.add(Face3D(p4, p5, p6, p7)) \\n            rawFaces.add(Face3D(p0, p1, p5, p4)) \\n            rawFaces.add(Face3D(p1, p2, p6, p5)) \\n            rawFaces.add(Face3D(p2, p3, p7, p6)) \\n            rawFaces.add(Face3D(p3, p0, p4, p7)) \\n            \\n            minZ = -s; maxZ = s\\n        } \\n        else if (exprClean == \\"paralelepipedo\\") {\\n            val sx = 4.0; val sy = 2.0; val sz = 3.0\\n            val p0 = Point3D(-sx, -sy, -sz); val p1 = Point3D(sx, -sy, -sz); val p2 = Point3D(sx, sy, -sz); val p3 = Point3D(-sx, sy, -sz)\\n            val p4 = Point3D(-sx, -sy, sz); val p5 = Point3D(sx, -sy, sz); val p6 = Point3D(sx, sy, sz); val p7 = Point3D(-sx, sy, sz)\\n            \\n            rawFaces.add(Face3D(p0, p1, p2, p3)); rawFaces.add(Face3D(p4, p5, p6, p7))\\n            rawFaces.add(Face3D(p0, p1, p5, p4)); rawFaces.add(Face3D(p1, p2, p6, p5))\\n            rawFaces.add(Face3D(p2, p3, p7, p6)); rawFaces.add(Face3D(p3, p0, p4, p7))\\n            \\n            minZ = -sz; maxZ = sz\\n        }\\n        else {\\n            val gridX = Array(gridSize + 1) { DoubleArray(gridSize + 1) }\\n            val gridY = Array(gridSize + 1) { DoubleArray(gridSize + 1) }\\n            val gridZ = Array(gridSize + 1) { DoubleArray(gridSize + 1) }\\n\\n            if (exprClean.contains(\\"sphere\\") || exprClean.contains(\\"esfera\\")) {\\n                val radius = 4.0\\n                for (i in 0..gridSize) {\\n                    val u = i * Math.PI / gridSize\\n                    for (j in 0..gridSize) {\\n                        val v = j * 2 * Math.PI / gridSize\\n                        gridX[i][j] = radius * Math.sin(u) * Math.cos(v)\\n                        gridY[i][j] = radius * Math.sin(u) * Math.sin(v)\\n                        gridZ[i][j] = radius * Math.cos(u)\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            } else if (exprClean.contains(\\"torus\\") || exprClean.contains(\\"toroide\\")) {\\n                val R = 3.0\\n                val r = 1.2\\n                for (i in 0..gridSize) {\\n                    val u = i * 2 * Math.PI / gridSize\\n                    for (j in 0..gridSize) {\\n                        val v = j * 2 * Math.PI / gridSize\\n                        gridX[i][j] = (R + r * Math.cos(v)) * Math.cos(u)\\n                        gridY[i][j] = (R + r * Math.cos(v)) * Math.sin(u)\\n                        gridZ[i][j] = r * Math.sin(v)\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            } else if (exprClean.contains(\\"cylinder\\") || exprClean.contains(\\"cilindro\\")) {\\n                val radius = 3.0\\n                for (i in 0..gridSize) {\\n                    val u = -4.0 + i * 8.0 / gridSize\\n                    for (j in 0..gridSize) {\\n                        val v = j * 2 * Math.PI / gridSize\\n                        gridX[i][j] = radius * Math.cos(v)\\n                        gridY[i][j] = radius * Math.sin(v)\\n                        gridZ[i][j] = u\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            } else if (exprClean.contains(\\"cone\\") && !exprClean.contains(\\"z\\")) {\\n                for (i in 0..gridSize) {\\n                    val u = i * 4.0 / gridSize\\n                    for (j in 0..gridSize) {\\n                        val v = j * 2 * Math.PI / gridSize\\n                        gridX[i][j] = u * Math.cos(v)\\n                        gridY[i][j] = u * Math.sin(v)\\n                        gridZ[i][j] = u - 2.0\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            } else if (exprClean.contains(\\";\\") && exprClean.count { it == ';' } >= 2) {\\n                val partes = exprClean.split(\\";\\")\\n                val parserX = MathParser3D(partes[0].trim())\\n                val parserY = MathParser3D(partes[1].trim())\\n                val parserZ = MathParser3D(partes[2].trim())\\n\\n                for (i in 0..gridSize) {\\n                    val u = -Math.PI + i * (2 * Math.PI) / gridSize\\n                    for (j in 0..gridSize) {\\n                        val v = -Math.PI + j * (2 * Math.PI) / gridSize\\n                        val x = parserX.parse(u, v)\\n                        val y = parserY.parse(u, v)\\n                        val z = parserZ.parse(u, v)\\n                        gridX[i][j] = if (x.isNaN() || x.isInfinite()) 0.0 else x\\n                        gridY[i][j] = if (y.isNaN() || y.isInfinite()) 0.0 else y\\n                        gridZ[i][j] = if (z.isNaN() || z.isInfinite()) 0.0 else z\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            } else if (exprClean.contains(\\"z\\")) {\\n                \\n                val parser3V = MathParser3D(expressao)\\n\\n                val gridX1 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n                val gridY1 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n                val gridZ1 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n\\n                val gridX2 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n                val gridY2 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n                val gridZ2 = Array(gridSize + 1) { DoubleArray(gridSize + 1) { Double.NaN } }\\n\\n                for (i in 0..gridSize) {\\n                    val x = -5.0 + i * 10.0 / gridSize\\n                    for (j in 0..gridSize) {\\n                        val y = -5.0 + j * 10.0 / gridSize\\n\\n                        val zRoots = mutableListOf<Double>()\\n                        var prevZ = -6.0\\n                        var prevVal = try { parser3V.parse(x, y, prevZ) } catch (and: Exception) { Double.NaN }\\n                        var currZ = -5.9\\n                        while (currZ <= 6.0) {\\n                            val currVal = try { parser3V.parse(x, y, currZ) } catch (and: Exception) { Double.NaN }\\n                            if (!prevVal.isNaN() && !currVal.isNaN() && !prevVal.isInfinite() && !currVal.isInfinite()) {\\n                                if (prevVal * currVal <= 0.0 || Math.abs(currVal) < 0.05) {\\n                                    val rootZ = if (Math.abs(currVal - prevVal) > 1e-5) {\\n                                        prevZ - prevVal * (currZ - prevZ) / (currVal - prevVal)\\n                                    } else {\\n                                        currZ\\n                                    }\\n                                    if (!rootZ.isNaN() && !rootZ.isInfinite() && rootZ in -6.0..6.0) {\\n                                        if (zRoots.isEmpty() || Math.abs(zRoots.last() - rootZ) > 0.2) {\\n                                            zRoots.add(rootZ)\\n                                        }\\n                                    }\\n                                }\\n                            }\\n                            prevZ = currZ\\n                            prevVal = currVal\\n                            currZ += 0.1\\n                        }\\n\\n                        if (zRoots.size >= 1) {\\n                            gridX1[i][j] = x\\n                            gridY1[i][j] = y\\n                            gridZ1[i][j] = zRoots[0]\\n                        }\\n                        if (zRoots.size >= 2) {\\n                            gridX2[i][j] = x\\n                            gridY2[i][j] = y\\n                            gridZ2[i][j] = zRoots[1]\\n                        }\\n                    }\\n                }\\n\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ1[i][j]\\n                        val z21 = gridZ1[i + 1][j]\\n                        val z22 = gridZ1[i + 1][j + 1]\\n                        val z12 = gridZ1[i][j + 1]\\n\\n                        if (!z11.isNaN() && !z21.isNaN() && !z22.isNaN() && !z12.isNaN()) {\\n                            if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                            if (z21 < minZ) minZ = z21; if (z21 > maxZ) maxZ = z21\\n                            if (z22 < minZ) minZ = z22; if (z22 > maxZ) maxZ = z22\\n                            if (z12 < minZ) minZ = z12; if (z12 > maxZ) maxZ = z12\\n\\n                            val p1 = Point3D(gridX1[i][j], gridY1[i][j], z11)\\n                            val p2 = Point3D(gridX1[i + 1][j], gridY1[i + 1][j], z21)\\n                            val p3 = Point3D(gridX1[i + 1][j + 1], gridY1[i + 1][j + 1], z22)\\n                            val p4 = Point3D(gridX1[i][j + 1], gridY1[i][j + 1], z12)\\n                            rawFaces.add(Face3D(p1, p2, p3, p4))\\n                        }\\n                    }\\n                }\\n\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ2[i][j]\\n                        val z21 = gridZ2[i + 1][j]\\n                        val z22 = gridZ2[i + 1][j + 1]\\n                        val z12 = gridZ2[i][j + 1]\\n\\n                        if (!z11.isNaN() && !z21.isNaN() && !z22.isNaN() && !z12.isNaN()) {\\n                            if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n                            if (z21 < minZ) minZ = z21; if (z21 > maxZ) maxZ = z21\\n                            if (z22 < minZ) minZ = z22; if (z22 > maxZ) maxZ = z22\\n                            if (z12 < minZ) minZ = z12; if (z12 > maxZ) maxZ = z12\\n\\n                            val p1 = Point3D(gridX2[i][j], gridY2[i][j], z11)\\n                            val p2 = Point3D(gridX2[i + 1][j], gridY2[i + 1][j], z21)\\n                            val p3 = Point3D(gridX2[i + 1][j + 1], gridY2[i + 1][j + 1], z22)\\n                            val p4 = Point3D(gridX2[i][j + 1], gridY2[i][j + 1], z12)\\n                            rawFaces.add(Face3D(p1, p2, p3, p4))\\n                        }\\n                    }\\n                }\\n            } else {\\n                val parser = MathParser3D(expressao)\\n                for (i in 0..gridSize) {\\n                    val x = -5.0 + i * 10.0 / gridSize\\n                    for (j in 0..gridSize) {\\n                        val y = -5.0 + j * 10.0 / gridSize\\n                        gridX[i][j] = x\\n                        gridY[i][j] = y\\n                        var z = try { parser.parse(x, y) } catch (and: Exception) { 0.0 }\\n                        gridZ[i][j] = if (z.isNaN() || z.isInfinite()) 0.0 else z\\n                    }\\n                }\\n                for (i in 0 until gridSize) {\\n                    for (j in 0 until gridSize) {\\n                        val z11 = gridZ[i][j]\\n                        val z21 = gridZ[i + 1][j]\\n                        val z22 = gridZ[i + 1][j + 1]\\n                        val z12 = gridZ[i][j + 1]\\n                        \\n                        if (z11 < minZ) minZ = z11; if (z11 > maxZ) maxZ = z11\\n\\n                        val p1 = Point3D(gridX[i][j], gridY[i][j], z11)\\n                        val p2 = Point3D(gridX[i + 1][j], gridY[i + 1][j], z21)\\n                        val p3 = Point3D(gridX[i + 1][j + 1], gridY[i + 1][j + 1], z22)\\n                        val p4 = Point3D(gridX[i][j + 1], gridY[i][j + 1], z12)\\n                        \\n                        rawFaces.add(Face3D(p1, p2, p3, p4))\\n                    }\\n                }\\n            }\\n        }\\n\\n        if (maxZ == minZ) maxZ = minZ + 1.0\\n\\n        val floorZ = minZ - 1.2\\n        val gridSteps = 8\\n\\n        for (i in 0..gridSteps) {\\n            val currVal = -5.0 + i * (10.0 / gridSteps)\\n            val pStart = project(currVal, -5.0, floorZ)\\n            val pEnd = project(currVal, 5.0, floorZ)\\n            canvas.drawLine(pStart.first, pStart.second, pEnd.first, pEnd.second, paintGridPlane)\\n\\n            val pStart2 = project(-5.0, currVal, floorZ)\\n            val pEnd2 = project(5.0, currVal, floorZ)\\n            canvas.drawLine(pStart2.first, pStart2.second, pEnd2.first, pEnd2.second, paintGridPlane)\\n        }\\n\\n        val originBottom = project(0.0, 0.0, floorZ)\\n        val originTop = project(0.0, 0.0, maxZ + 1.5)\\n        canvas.drawLine(originBottom.first, originBottom.second, originTop.first, originTop.second, paintAxisZ)\\n\\n        val xAxisStart = project(-5.0, 0.0, floorZ)\\n        val xAxisEnd = project(5.0, 0.0, floorZ)\\n        canvas.drawLine(xAxisStart.first, xAxisStart.second, xAxisEnd.first, xAxisEnd.second, paintAxisX)\\n\\n        val yAxisStart = project(0.0, -5.0, floorZ)\\n        val yAxisEnd = project(0.0, 5.0, floorZ)\\n        canvas.drawLine(yAxisStart.first, yAxisStart.second, yAxisEnd.first, yAxisEnd.second, paintAxisY)\\n\\n        val tickSteps = 4\\n        for (k in -tickSteps..tickSteps) {\\n            if (k == 0) continue\\n            val valCoord = k * (5.0 / tickSteps)\\n            val pX = project(valCoord, 0.0, floorZ)\\n            canvas.drawText(valCoord.toInt().toString(), pX.first, pX.second + 22f, paintAxisText)\\n\\n            val pY = project(0.0, valCoord, floorZ)\\n            canvas.drawText(valCoord.toInt().toString(), pY.first - 18f, pY.second + 6f, paintAxisText)\\n        }\\n\\n        val zSteps = 3\\n        val zRange = maxZ - minZ\\n        for (k in 1..zSteps) {\\n            val zVal = minZ + k * (zRange / zSteps)\\n            val pZ = project(0.0, 0.0, zVal)\\n            canvas.drawText(String.format(\\"%.1f\\", zVal), pZ.first - 30f, pZ.second + 6f, paintAxisText)\\n        }\\n\\n        val quads = mutableListOf<Quad3D>()\\n        for (face in rawFaces) {\\n            val p1 = project(face.p1.x, face.p1.y, face.p1.z)\\n            val p2 = project(face.p2.x, face.p2.y, face.p2.z)\\n            val p3 = project(face.p3.x, face.p3.y, face.p3.z)\\n            val p4 = project(face.p4.x, face.p4.y, face.p4.z)\\n\\n            val avgDepth = (p1.third + p2.third + p3.third + p4.third) / 4f\\n            val avgRawZ = ((face.p1.z + face.p2.z + face.p3.z + face.p4.z) / 4.0).toFloat()\\n\\n            quads.add(Quad3D(\\n                p1.first, p1.second, p2.first, p2.second, \\n                p3.first, p3.second, p4.first, p4.second, \\n                avgDepth, avgRawZ\\n            ))\\n        }\\n\\n        quads.sortBy { it.avgZ }\\n\\n        val paintFill = Paint().apply { style = Paint.Style.FILL; isAntiAlias = true }\\n        val paintStroke = Paint().apply { style = Paint.Style.STROKE; strokeWidth = 1.0f; color = Color.parseColor(\\"#1E293B\\"); isAntiAlias = true }\\n        val path = Path()\\n\\n        for (quad in quads) {\\n            val normZ = ((quad.rawZ - minZ) / (maxZ - minZ)).coerceIn(0.0, 1.0).toFloat()\\n            val hue = (240f - normZ * 240f)\\n            val colorVal = Color.HSVToColor(floatArrayOf(hue, 0.85f, 0.95f))\\n\\n            paintFill.color = colorVal\\n\\n            path.reset()\\n            path.moveTo(quad.p1x, quad.p1y)\\n            path.lineTo(quad.p2x, quad.p2y)\\n            path.lineTo(quad.p3x, quad.p3y)\\n            path.lineTo(quad.p4x, quad.p4y)\\n            path.close()\\n\\n            canvas.drawPath(path, paintFill)\\n            canvas.drawPath(path, paintStroke)\\n        }\\n\\n        return bitmap\\n    }\\n}\\n", "grafico_2d.scriptk": "\\n\\nimport android.os.Bundle\\nimport android.annotation.SuppressLint\\nimport android.graphics.Bitmap\\nimport android.graphics.BitmapFactory\\nimport android.graphics.Canvas\\nimport android.graphics.Color\\nimport android.graphics.Paint\\nimport android.graphics.Path\\nimport android.text.Editable\\nimport android.text.Spanned\\nimport android.text.TextWatcher\\nimport android.text.SpannableStringBuilder\\nimport android.text.style.SuperscriptSpan\\nimport android.text.style.RelativeSizeSpan\\nimport android.text.style.ForegroundColorSpan\\nimport android.view.MotionEvent\\nimport android.view.ScaleGestureDetector\\nimport android.widget.Button\\nimport android.widget.EditText\\nimport android.widget.ImageView\\nimport androidx.appcompat.app.AppCompatActivity\\n\\nclass MathParser(private val expr: String) {\\n    private val expression = expr\\n        .replace(\\"\\u00b2\\", \\"^2\\")\\n        .replace(\\"\\u00b3\\", \\"^3\\")\\n        .replace(\\"\\u00b9\\", \\"^1\\")\\n        .replace(\\"\\u2074\\", \\"^4\\")\\n        .replace(\\"**\\", \\"^\\")\\n    private var pos = -1\\n    private var ch = 0\\n\\n    private fun nextChar() {\\n        pos++\\n        ch = if (pos < expression.length) expression[pos].code else -1\\n    }\\n\\n    private fun eat(charToEat: Int): Boolean {\\n        while (ch == ' '.code) nextChar()\\n        if (ch == charToEat) {\\n            nextChar()\\n            return true\\n        }\\n        return false\\n    }\\n\\n    fun parse(xVal: Double): Double {\\n        pos = -1\\n        nextChar()\\n        return parseExpression(xVal)\\n    }\\n\\n    private fun parseExpression(xVal: Double): Double {\\n        var x = parseTerm(xVal)\\n        while (true) {\\n            if (eat('+'.code)) x += parseTerm(xVal)\\n            else if (eat('-'.code)) x -= parseTerm(xVal)\\n            else return x\\n        }\\n    }\\n\\n    private fun parseTerm(xVal: Double): Double {\\n        var x = parseFactor(xVal)\\n        while (true) {\\n            if (eat('*'.code)) x *= parseFactor(xVal)\\n            else if (eat('/'.code)) x /= parseFactor(xVal)\\n            else return x\\n        }\\n    }\\n\\n    private fun parseFactor(xVal: Double): Double {\\n        if (eat('+'.code)) return parseFactor(xVal)\\n        if (eat('-'.code)) return -parseFactor(xVal)\\n\\n        val startPos = this.pos\\n        var x = 0.0\\n\\n        if (eat('('.code)) {\\n            x = parseExpression(xVal)\\n            eat(')'.code)\\n        } else if ((ch >= '0'.code && ch <= '9'.code) || ch == '.'.code) {\\n            while ((ch >= '0'.code && ch <= '9'.code) || ch == '.'.code) nextChar()\\n            x = expression.substring(startPos, this.pos).toDoubleOrNull() ?: 0.0\\n        } else if ((ch >= 'a'.code && ch <= 'z'.code) || (ch >= 'A'.code && ch <= 'Z'.code)) {\\n            while ((ch >= 'a'.code && ch <= 'z'.code) || (ch >= 'A'.code && ch <= 'Z'.code)) nextChar()\\n            val func = expression.substring(startPos, this.pos).lowercase()\\n            if (func == \\"x\\") {\\n                x = xVal\\n            } else if (func == \\"and\\") {\\n                x = Math.E\\n            } else if (func == \\"pi\\") {\\n                x = Math.PI\\n            } else if (eat('('.code)) {\\n                val arg = parseExpression(xVal)\\n                eat(')'.code)\\n                x = when (func) {\\n                    \\"sin\\" -> Math.sin(arg)\\n                    \\"cos\\" -> Math.cos(arg)\\n                    \\"tan\\" -> Math.tan(arg)\\n                    \\"sqrt\\" -> Math.sqrt(arg)\\n                    \\"abs\\" -> Math.abs(arg)\\n                    \\"exp\\" -> Math.exp(arg)\\n                    \\"log\\", \\"ln\\" -> Math.log(arg)\\n                    else -> 0.0\\n                }\\n            }\\n        }\\n\\n        if (eat('^'.code)) x = Math.pow(x, parseFactor(xVal))\\n\\n        return x\\n    }\\n}\\n\\nclass Grafico_2dActivity : AppCompatActivity() {\\n\\n    private var isUpdatingText = false\\n\\n    \\n    private var lastTouchX = 0f\\n    private var lastTouchY = 0f\\n    private var currentXMin = -10.0\\n    private var currentXMax = 10.0\\n    private var currentYMin = -10.0\\n    private var currentYMax = 10.0\\n\\n    \\n    private lateinit var scaleDetector: ScaleGestureDetector\\n\\n    @SuppressLint(\\"ClickableViewAccessibility\\")\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContentView(R.layout.grafico_2d)\\n\\n        try {\\n            val logoView = findViewById<ImageView>(R.id.logo2)\\n            val inputStream = assets.open(\\"logo2.png\\")\\n            val bitmap = BitmapFactory.decodeStream(inputStream)\\n            logoView?.setImageBitmap(bitmap)\\n        } catch (and: Exception) {\\n            and.printStackTrace()\\n        }\\n\\n        val edtFuncao = findViewById<EditText>(R.id.edtFuncao)\\n        val btnGerarGrafico = findViewById<Button>(R.id.btnGerarGrafico)\\n        val imgGraficoCanvas = findViewById<ImageView>(R.id.imgGraficoCanvas)\\n\\n        edtFuncao?.addTextChangedListener(object : TextWatcher {\\n            override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}\\n            override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}\\n            override fun afterTextChanged(s: Editable?) {\\n                if (isUpdatingText || s == null) return\\n                isUpdatingText = true\\n\\n                val rawText = s.toString()\\n                val spannable = SpannableStringBuilder(rawText)\\n                val pattern = Regex(\\"(\\\\\\\\*\\\\\\\\*|\\\\\\\\^)([0-9xX]+)\\")\\n                val matches = pattern.findAll(rawText)\\n\\n                for (match in matches) {\\n                    val opRange = match.groups[1]?.range ?: continue\\n                    val expRange = match.groups[2]?.range ?: continue\\n\\n                    spannable.setSpan(ForegroundColorSpan(Color.TRANSPARENT), opRange.first, opRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                    spannable.setSpan(RelativeSizeSpan(0.0f), opRange.first, opRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                    spannable.setSpan(SuperscriptSpan(), expRange.first, expRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                    spannable.setSpan(RelativeSizeSpan(0.75f), expRange.first, expRange.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)\\n                }\\n\\n                val currentSelStart = edtFuncao.selectionStart\\n                val currentSelEnd = edtFuncao.selectionEnd\\n                edtFuncao.setText(spannable)\\n                try {\\n                    edtFuncao.setSelection(\\n                        Math.min(currentSelStart, spannable.length),\\n                        Math.min(currentSelEnd, spannable.length)\\n                    )\\n                } catch (and: Exception) {\\n                    edtFuncao.setSelection(edtFuncao.text?.length ?: 0)\\n                }\\n\\n                isUpdatingText = false\\n            }\\n        })\\n\\n        \\n        scaleDetector = ScaleGestureDetector(this, object : ScaleGestureDetector.SimpleOnScaleGestureListener() {\\n            override fun onScale(detector: ScaleGestureDetector): Boolean {\\n                val factor = detector.scaleFactor\\n                val spanX = currentXMax - currentXMin\\n                val spanY = currentYMax - currentYMin\\n                \\n                \\n                val newSpanX = spanX / factor\\n                val newSpanY = spanY / factor\\n                \\n                val midX = (currentXMax + currentXMin) / 2\\n                val midY = (currentYMax + currentYMin) / 2\\n                \\n                currentXMin = midX - newSpanX / 2\\n                currentXMax = midX + newSpanX / 2\\n                currentYMin = midY - newSpanY / 2\\n                currentYMax = midY + newSpanY / 2\\n                \\n                val expressao = edtFuncao?.text?.toString() ?: \\"x**2\\"\\n                imgGraficoCanvas?.setImageBitmap(desenharGrafico(expressao))\\n                return true\\n            }\\n        })\\n\\n        \\n        imgGraficoCanvas?.setOnTouchListener { _, event ->\\n            scaleDetector.onTouchEvent(event)\\n            \\n            if (!scaleDetector.isInProgress) {\\n                when (event.action) {\\n                    MotionEvent.ACTION_DOWN -> {\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                    MotionEvent.ACTION_MOVE -> {\\n                        val dx = event.x - lastTouchX\\n                        val dy = event.y - lastTouchY\\n\\n                        val width = imgGraficoCanvas.width.toFloat()\\n                        val height = imgGraficoCanvas.height.toFloat()\\n                        val margin = 60f\\n\\n                        \\n                        val rangeX = currentXMax - currentXMin\\n                        val rangeY = currentYMax - currentYMin\\n                        \\n                        val mathDx = (dx / (width - 2 * margin)) * rangeX\\n                        val mathDy = (dy / (height - 2 * margin)) * rangeY\\n\\n                        \\n                        currentXMin -= mathDx\\n                        currentXMax -= mathDx\\n                        currentYMin += mathDy \\n                        currentYMax += mathDy\\n\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n\\n                        val expressao = edtFuncao?.text?.toString() ?: \\"x**2\\"\\n                        imgGraficoCanvas.setImageBitmap(desenharGrafico(expressao))\\n                    }\\n                }\\n            }\\n            true\\n        }\\n\\n        btnGerarGrafico?.setOnClickListener {\\n            \\n            currentXMin = -10.0; currentXMax = 10.0\\n            currentYMin = -10.0; currentYMax = 10.0\\n            \\n            val expressao = edtFuncao?.text?.toString() ?: \\"x**2\\"\\n            val bitmapGrafico = desenharGrafico(expressao)\\n            imgGraficoCanvas?.setImageBitmap(bitmapGrafico)\\n        }\\n\\n        val bitmapInicial = desenharGrafico(\\"x**2 - 4\\")\\n        imgGraficoCanvas?.setImageBitmap(bitmapInicial)\\n    }\\n\\n    private fun desenharGrafico(expressao: String): Bitmap {\\n        val width = 800\\n        val height = 800\\n        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n\\n        val paintGrid = Paint().apply { color = Color.parseColor(\\"#E2E8F0\\"); strokeWidth = 2f; isAntiAlias = true }\\n        val paintEixos = Paint().apply { color = Color.parseColor(\\"#334155\\"); strokeWidth = 4f; isAntiAlias = true }\\n        val paintTexto = Paint().apply { color = Color.parseColor(\\"#475569\\"); textSize = 20f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n        \\n        val paintLinhaGrafico = Paint().apply { color = Color.parseColor(\\"#0066FF\\"); strokeWidth = 5f; isAntiAlias = true; style = Paint.Style.STROKE; strokeJoin = Paint.Join.ROUND }\\n        val paintPoligonoFill = Paint().apply { color = Color.parseColor(\\"#330066FF\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n        val paintPonto = Paint().apply { color = Color.parseColor(\\"#DC2626\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n\\n        val margin = 60f\\n        \\n        \\n        fun proj(x: Double, y: Double): Pair<Float, Float> {\\n            val px = (margin + (x - currentXMin) / (currentXMax - currentXMin) * (width - 2 * margin)).toFloat()\\n            val py = ((height - margin) - (y - currentYMin) / (currentYMax - currentYMin) * (height - 2 * margin)).toFloat()\\n            return Pair(px, py)\\n        }\\n\\n        \\n        val rangeX = currentXMax - currentXMin\\n        val stepX = Math.max(1.0, Math.round(rangeX / 10.0).toDouble())\\n        \\n        var startX = Math.floor(currentXMin / stepX) * stepX\\n        while (startX <= currentXMax) {\\n            val (px, _) = proj(startX, 0.0)\\n            if (px in margin..(width - margin)) {\\n                canvas.drawLine(px, margin, px, height - margin, paintGrid)\\n                if (startX != 0.0) {\\n                    val (_, py0) = proj(0.0, 0.0)\\n                    val safePy0 = py0.coerceIn(margin + 20f, height - margin - 10f)\\n                    canvas.drawText(String.format(\\"%.1f\\", startX).replace(\\".0\\", \\"\\"), px, safePy0 + 30f, paintTexto)\\n                }\\n            }\\n            startX += stepX\\n        }\\n\\n        val rangeY = currentYMax - currentYMin\\n        val stepY = Math.max(1.0, Math.round(rangeY / 10.0).toDouble())\\n        var startY = Math.floor(currentYMin / stepY) * stepY\\n        while (startY <= currentYMax) {\\n            val (_, py) = proj(0.0, startY)\\n            if (py in margin..(height - margin)) {\\n                canvas.drawLine(margin, py, width - margin, py, paintGrid)\\n                if (startY != 0.0) {\\n                    val (px0, _) = proj(0.0, 0.0)\\n                    val safePx0 = px0.coerceIn(margin + 30f, width - margin - 20f)\\n                    canvas.drawText(String.format(\\"%.1f\\", startY).replace(\\".0\\", \\"\\"), safePx0 - 30f, py + 8f, paintTexto)\\n                }\\n            }\\n            startY += stepY\\n        }\\n\\n        \\n        val (ox, oy) = proj(0.0, 0.0)\\n        if (oy in margin..(height - margin)) canvas.drawLine(margin, oy, width - margin, oy, paintEixos)\\n        if (ox in margin..(width - margin)) canvas.drawLine(ox, margin, ox, height - margin, paintEixos)\\n\\n        \\n        canvas.clipRect(margin, margin, width - margin, height - margin)\\n\\n        \\n        val regexPontos = Regex(\\"\\\\\\\\(\\\\\\\\s*(-?\\\\\\\\d+\\\\\\\\.?\\\\\\\\d*)\\\\\\\\s*,\\\\\\\\s*(-?\\\\\\\\d+\\\\\\\\.?\\\\\\\\d*)\\\\\\\\s*\\\\\\\\)\\")\\n        val matchesPontos = regexPontos.findAll(expressao).toList()\\n\\n        if (matchesPontos.isNotEmpty()) {\\n            \\n            val path = Path()\\n            var primeiroPonto = true\\n\\n            for ((index, match) in matchesPontos.withIndex()) {\\n                val pxMath = match.groupValues[1].toDouble()\\n                val pyMath = match.groupValues[2].toDouble()\\n                val (pxScr, pyScr) = proj(pxMath, pyMath)\\n\\n                if (primeiroPonto) {\\n                    path.moveTo(pxScr, pyScr)\\n                    primeiroPonto = false\\n                } else {\\n                    path.lineTo(pxScr, pyScr)\\n                }\\n\\n                \\n                canvas.drawCircle(pxScr, pyScr, 8f, paintPonto)\\n                canvas.drawText(String.format(\\"%c\\", 'A'.code + (index % 26)), pxScr + 15f, pyScr - 15f, paintTexto)\\n            }\\n\\n            \\n            if (matchesPontos.size > 2) {\\n                path.close()\\n                canvas.drawPath(path, paintPoligonoFill)\\n            }\\n            canvas.drawPath(path, paintLinhaGrafico)\\n\\n        } else {\\n            \\n            try {\\n                val parser = MathParser(expressao)\\n                var prevPx: Float? = null\\n                var prevPy: Float? = null\\n\\n                val steps = 400\\n                for (step in 0..steps) {\\n                    val xVal = currentXMin + step * (currentXMax - currentXMin) / steps\\n                    val yVal = parser.parse(xVal)\\n\\n                    if (!yVal.isNaN() && !yVal.isInfinite() && yVal >= currentYMin - (currentYMax-currentYMin) && yVal <= currentYMax + (currentYMax-currentYMin)) {\\n                        val (px, py) = proj(xVal, yVal)\\n\\n                        if (prevPx != null && prevPy != null) {\\n                            canvas.drawLine(prevPx, prevPy, px, py, paintLinhaGrafico)\\n                        }\\n                        prevPx = px\\n                        prevPy = py\\n                    } else {\\n                        prevPx = null\\n                        prevPy = null\\n                    }\\n                }\\n            } catch (and: Exception) {\\n                and.printStackTrace()\\n            }\\n        }\\n\\n        return bitmap\\n    }\\n}", "grafico_estatistico.scriptk": "\\n\\nimport android.os.Bundle\\nimport android.annotation.SuppressLint\\nimport android.graphics.Bitmap\\nimport android.graphics.BitmapFactory\\nimport android.graphics.Canvas\\nimport android.graphics.Color\\nimport android.graphics.Matrix\\nimport android.graphics.Paint\\nimport android.graphics.Path\\nimport android.view.MotionEvent\\nimport android.view.ScaleGestureDetector\\nimport android.widget.Button\\nimport android.widget.EditText\\nimport android.widget.ImageView\\nimport android.widget.TextView\\nimport androidx.appcompat.app.AppCompatActivity\\n\\nclass Grafico_estatisticoActivity : AppCompatActivity() {\\n\\n    \\n    private lateinit var scaleDetector: ScaleGestureDetector\\n    private val matrix = Matrix()\\n    private var scaleFactor = 1.0f\\n    private var lastTouchX = 0f\\n    private var lastTouchY = 0f\\n\\n    @SuppressLint(\\"ClickableViewAccessibility\\")\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContentView(R.layout.grafico_estatistico)\\n\\n        try {\\n            val logoView = findViewById<ImageView>(R.id.logo4)\\n            val inputStream = assets.open(\\"logo4.png\\")\\n            val bitmap = BitmapFactory.decodeStream(inputStream)\\n            logoView?.setImageBitmap(bitmap)\\n        } catch (and: Exception) {\\n            and.printStackTrace()\\n        }\\n\\n        val edtDados = findViewById<EditText>(R.id.edtDadosEstatisticos)\\n        val btnCalcular = findViewById<Button>(R.id.btnCalcularEstatistica)\\n        val txtResultados = findViewById<TextView>(R.id.txtResultados)\\n        val imgCanvas = findViewById<ImageView>(R.id.imgGraficoCanvasEstatistico)\\n\\n        \\n        imgCanvas?.scaleType = ImageView.ScaleType.MATRIX\\n\\n        \\n        scaleDetector = ScaleGestureDetector(this, object : ScaleGestureDetector.SimpleOnScaleGestureListener() {\\n            override fun onScale(detector: ScaleGestureDetector): Boolean {\\n                scaleFactor *= detector.scaleFactor\\n                scaleFactor = scaleFactor.coerceIn(1.0f, 6.0f) \\n                \\n                matrix.setScale(scaleFactor, scaleFactor, detector.focusX, detector.focusY)\\n                imgCanvas?.imageMatrix = matrix\\n                return true\\n            }\\n        })\\n\\n        \\n        imgCanvas?.setOnTouchListener { _, event ->\\n            scaleDetector.onTouchEvent(event)\\n            \\n            if (!scaleDetector.isInProgress) {\\n                when (event.action) {\\n                    MotionEvent.ACTION_DOWN -> {\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                    MotionEvent.ACTION_MOVE -> {\\n                        val dx = event.x - lastTouchX\\n                        val dy = event.y - lastTouchY\\n                        matrix.postTranslate(dx, dy)\\n                        imgCanvas.imageMatrix = matrix\\n                        \\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                }\\n            }\\n            true\\n        }\\n\\n        btnCalcular?.setOnClickListener {\\n            \\n            scaleFactor = 1.0f\\n            matrix.reset()\\n            imgCanvas?.imageMatrix = matrix\\n\\n            val entradaTexto = edtDados?.text?.toString() ?: \\"\\"\\n            processarEMostrarGrafico(entradaTexto, txtResultados, imgCanvas)\\n        }\\n\\n        val amostraPadrao = \\"12, 15, 14, 10, 18, 22, 15, 16, 17, 19, 13, 15, 14, 16, 20, 21, 11, 14, 16, 17\\"\\n        edtDados?.setText(amostraPadrao)\\n        processarEMostrarGrafico(amostraPadrao, txtResultados, imgCanvas)\\n    }\\n\\n    private fun processarEMostrarGrafico(\\n        str: String,\\n        txtResultados: TextView?,\\n        imgCanvas: ImageView?\\n    ) {\\n        val numeros = str.split(\\",\\")\\n            .mapNotNull { it.trim().toDoubleOrNull() }\\n\\n        if (numeros.size < 2) {\\n            txtResultados?.setText(\\"Insira pelo menos 2 numeros validos separados por virgula.\\")\\n            val emptyBitmap = Bitmap.createBitmap(800, 800, Bitmap.Config.ARGB_8888)\\n            val canvas = Canvas(emptyBitmap)\\n            canvas.drawColor(Color.WHITE)\\n            imgCanvas?.setImageBitmap(emptyBitmap)\\n            return\\n        }\\n\\n        val n = numeros.size\\n        val media = numeros.average()\\n        \\n        \\n        val esperanca = media\\n        \\n        val somaQuadradosDiferenca = numeros.sumOf { Math.pow(it - media, 2.0) }\\n        val variancia = somaQuadradosDiferenca / (n - 1)\\n        val desvioPadrao = Math.sqrt(variancia)\\n\\n        \\n        val frequencias = numeros.groupingBy { it }.eachCount()\\n        val maxFreq = frequencias.values.maxOrNull() ?: 0\\n        val modas = frequencias.filter { it.value == maxFreq }.keys\\n        val modaStr = if (modas.size == numeros.size) \\"Amodal\\" else modas.joinToString(\\", \\") { String.format(\\"%.1f\\", it) }\\n\\n        \\n        val desvioPadraoPop = Math.sqrt(numeros.sumOf { Math.pow(it - media, 2.0) } / n)\\n        val curtose = if (desvioPadraoPop > 0.0) {\\n            (numeros.sumOf { Math.pow(it - media, 4.0) } / n) / Math.pow(desvioPadraoPop, 4.0)\\n        } else 0.0\\n        \\n        val tipoCurtose = when {\\n            Math.abs(curtose - 3.0) < 0.2 -> \\"Mesoc\\u00fartica\\"\\n            curtose > 3.0 -> \\"Leptoc\\u00fartica\\"\\n            else -> \\"Platic\\u00fartica\\"\\n        }\\n\\n        val textoRes = String.format(\\n            \\"Esperan\\u00e7a E[X]: %.2f | Var: %.2f | Desvio P: %.2f\\\\nModa: %s | Curtose: %.2f (%s)\\", \\n            esperanca, variancia, desvioPadrao, modaStr, curtose, tipoCurtose\\n        )\\n        txtResultados?.setText(textoRes)\\n\\n        val bitmap = desenharHistogramaEGauss(numeros, media, desvioPadrao)\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun desenharHistogramaEGauss(\\n        dados: List<Double>,\\n        media: Double,\\n        desvioPadrao: Double\\n    ): Bitmap {\\n        val width = 900\\n        val height = 800\\n        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n\\n        val margin = 80f\\n        val renderWidth = width - 2 * margin\\n        val renderHeight = height - 2 * margin\\n\\n        val minData = dados.minOrNull() ?: 0.0\\n        val maxData = dados.maxOrNull() ?: 1.0\\n\\n        val rangeVal = if (maxData == minData) 1.0 else maxData - minData\\n        val numBins = Math.min(10, Math.max(5, Math.sqrt(dados.size.toDouble()).toInt()))\\n        val binWidthData = rangeVal / numBins\\n\\n        val counts = IntArray(numBins)\\n        for (v in dados) {\\n            var binIndex = ((v - minData) / binWidthData).toInt()\\n            if (binIndex >= numBins) binIndex = numBins - 1\\n            if (binIndex < 0) binIndex = 0\\n            counts[binIndex]++\\n        }\\n\\n        val maxCount = (counts.maxOrNull() ?: 1).toDouble()\\n\\n        val paintGrid = Paint().apply {\\n            color = Color.parseColor(\\"#E2E8F0\\")\\n            strokeWidth = 2f\\n            isAntiAlias = true\\n        }\\n\\n        val paintAxis = Paint().apply {\\n            color = Color.parseColor(\\"#334155\\")\\n            strokeWidth = 4f\\n            isAntiAlias = true\\n        }\\n\\n        val paintText = Paint().apply {\\n            color = Color.parseColor(\\"#475569\\")\\n            textSize = 20f\\n            isAntiAlias = true\\n            textAlign = Paint.Align.CENTER\\n        }\\n\\n        val paintBarFill = Paint().apply {\\n            color = Color.parseColor(\\"#93C5FD\\")\\n            style = Paint.Style.FILL\\n            isAntiAlias = true\\n        }\\n\\n        val paintBarStroke = Paint().apply {\\n            color = Color.parseColor(\\"#2563EB\\")\\n            style = Paint.Style.STROKE\\n            strokeWidth = 3f\\n            isAntiAlias = true\\n        }\\n\\n        val paintGaussLine = Paint().apply {\\n            color = Color.parseColor(\\"#DC2626\\")\\n            strokeWidth = 6f\\n            style = Paint.Style.STROKE\\n            isAntiAlias = true\\n        }\\n\\n        val paintMeanLine = Paint().apply {\\n            color = Color.parseColor(\\"#16A34A\\")\\n            strokeWidth = 4f\\n            style = Paint.Style.STROKE\\n            isAntiAlias = true\\n        }\\n\\n        val yTicks = 5\\n        for (i in 0..yTicks) {\\n            val yVal = (maxCount * i / yTicks)\\n            val py = height - margin - (i.toFloat() / yTicks) * renderHeight\\n            canvas.drawLine(margin, py, width - margin, py, paintGrid)\\n\\n            val paintTextLeft = Paint(paintText).apply { textAlign = Paint.Align.RIGHT }\\n            canvas.drawText(String.format(\\"%.0f\\", yVal), margin - 15f, py + 6f, paintTextLeft)\\n        }\\n\\n        val barWidthPx = renderWidth / numBins\\n        for (i in 0 until numBins) {\\n            val left = margin + i * barWidthPx\\n            val right = left + barWidthPx\\n            val barHeightPx = (counts[i] / maxCount * renderHeight).toFloat()\\n            val top = height - margin - barHeightPx\\n            val bottom = height - margin\\n\\n            canvas.drawRect(left, top, right, bottom, paintBarFill)\\n            canvas.drawRect(left, top, right, bottom, paintBarStroke)\\n\\n            val binCenterData = minData + (i + 0.5) * binWidthData\\n            canvas.drawText(String.format(\\"%.1f\\", binCenterData), left + barWidthPx / 2f, height - margin + 35f, paintText)\\n        }\\n\\n        canvas.drawLine(margin, height - margin, width - margin, height - margin, paintAxis)\\n        canvas.drawLine(margin, margin, margin, height - margin, paintAxis)\\n\\n        if (desvioPadrao > 0.0) {\\n            val totalAreaHistogram = dados.size * binWidthData\\n            val pathGauss = Path()\\n            var started = false\\n\\n            val steps = 300\\n            val xStartData = minData - binWidthData\\n            val xEndData = maxData + binWidthData\\n\\n            for (s in 0..steps) {\\n                val xVal = xStartData + s * (xEndData - xStartData) / steps\\n                val exponent = -0.5 * Math.pow((xVal - media) / desvioPadrao, 2.0)\\n                val pdf = (1.0 / (desvioPadrao * Math.sqrt(2.0 * Math.PI))) * Math.exp(exponent)\\n                val expectedCountDensity = pdf * totalAreaHistogram / binWidthData\\n\\n                val px = (margin + ((xVal - minData) / rangeVal) * renderWidth).toFloat()\\n                val py = (height - margin - (expectedCountDensity / maxCount) * renderHeight).toFloat()\\n\\n                if (px in margin..(width - margin)) {\\n                    if (!started) {\\n                        pathGauss.moveTo(px, py.coerceIn(margin, height - margin))\\n                        started = true\\n                    } else {\\n                        pathGauss.lineTo(px, py.coerceIn(margin, height - margin))\\n                    }\\n                }\\n            }\\n            canvas.drawPath(pathGauss, paintGaussLine)\\n        }\\n\\n        val meanPx = (margin + ((media - minData) / rangeVal) * renderWidth).toFloat()\\n        if (meanPx in margin..(width - margin)) {\\n            canvas.drawLine(meanPx, margin, meanPx, height - margin, paintMeanLine)\\n            val paintMeanText = Paint(paintText).apply {\\n                color = Color.parseColor(\\"#16A34A\\")\\n                textAlign = Paint.Align.CENTER\\n                isFakeBoldText = true\\n            }\\n            canvas.drawText(String.format(\\"E[X] = %.2f\\", media), meanPx, margin - 15f, paintMeanText)\\n        }\\n\\n        return bitmap\\n    }\\n}", "grafico_probabilidade.scriptk": "\\nimport android.app.AlertDialog\\nimport android.os.Bundle\\nimport android.annotation.SuppressLint\\nimport android.content.Context\\nimport android.net.ConnectivityManager\\nimport android.net.NetworkCapabilities\\nimport android.graphics.Bitmap\\nimport android.graphics.BitmapFactory\\nimport android.graphics.Canvas\\nimport android.graphics.Color\\nimport android.graphics.Matrix\\nimport android.graphics.Paint\\nimport android.graphics.Path\\nimport android.view.MotionEvent\\nimport android.view.ScaleGestureDetector\\nimport android.widget.Button\\nimport android.widget.EditText\\nimport android.widget.ImageView\\nimport android.widget.TextView\\nimport androidx.appcompat.app.AppCompatActivity\\nimport androidx.core.text.HtmlCompat\\nimport androidx.lifecycle.lifecycleScope\\nimport kotlinx.coroutines.Dispatchers\\nimport kotlinx.coroutines.launch\\nimport kotlinx.coroutines.withContext\\nimport org.json.JSONObject\\nimport java.net.HttpURLConnection\\nimport java.net.URL\\nimport kotlin.math.exp\\nimport kotlin.math.pow\\nimport kotlin.math.sqrt\\n\\nclass Grafico_probabilidadeActivity : AppCompatActivity() {\\n\\n    private var scaleDetector: ScaleGestureDetector? = null\\n    private val matrix = Matrix()\\n    private var scaleFactor = 1.0f\\n    private var lastTouchX = 0f\\n    private var lastTouchY = 0f\\n\\n    @SuppressLint(\\"ClickableViewAccessibility\\")\\n    override fun onCreate(savedInstanceState: Bundle?) {\\n        super.onCreate(savedInstanceState)\\n        setContentView(R.layout.grafico_probabilidade)\\n\\n        try {\\n            val logoView = findViewById<ImageView>(R.id.logo5)\\n            val inputStream = assets.open(\\"logo5.png\\")\\n            val bitmap = BitmapFactory.decodeStream(inputStream)\\n            if (bitmap != null) {\\n                logoView?.setImageBitmap(bitmap)\\n            }\\n        } catch (and: Exception) {\\n            and.printStackTrace()\\n        }\\n\\n        val edtProblema = findViewById<EditText>(R.id.edtProblemaProbabilidade)\\n        val btnCalcular = findViewById<Button>(R.id.btnCalcularProbabilidade)\\n        val txtResultado = findViewById<TextView>(R.id.txtResultadoProbabilidade)\\n        val imgCanvas = findViewById<ImageView>(R.id.imgCanvasProbabilidade)\\n        val txtTituloApp = findViewById<TextView>(R.id.txtTituloApp)\\n        val edtSeletorModulo = findViewById<EditText>(R.id.edtSeletorModulo)\\n\\n        val listaModulos = arrayOf(\\n            \\"Distribui\\u00e7\\u00e3o Normal (Gaussiana)\\",\\n            \\"Distribui\\u00e7\\u00e3o Binomial\\",\\n            \\"Distribui\\u00e7\\u00e3o de Poisson\\",\\n            \\"Teorema de Bayes\\",\\n            \\"Probabilidade Condicional\\",\\n            \\"An\\u00e1lise Combinat\\u00f3ria\\",\\n            \\"Bin\\u00f4mio de Newton\\",\\n            \\"Cadeias de Markov\\",\\n            \\"Espa\\u00e7o Amostral Discreto\\"\\n        )\\n        \\n        edtSeletorModulo?.setText(listaModulos[8])\\n\\n        edtSeletorModulo?.setOnClickListener {\\n            AlertDialog.Builder(this)\\n                .setTitle(\\"Selecione o M\\u00f3dulo\\")\\n                .setItems(listaModulos) { _, which ->\\n                    edtSeletorModulo?.setText(listaModulos[which])\\n                }\\n                .show()\\n        }\\n\\n        imgCanvas?.scaleType = ImageView.ScaleType.MATRIX\\n\\n        scaleDetector = ScaleGestureDetector(this, object : ScaleGestureDetector.SimpleOnScaleGestureListener() {\\n            override fun onScale(detector: ScaleGestureDetector): Boolean {\\n                val prevScale = scaleFactor\\n                scaleFactor *= detector.scaleFactor\\n                scaleFactor = scaleFactor.coerceIn(1.0f, 6.0f)\\n                val factor = scaleFactor / prevScale\\n                matrix.postScale(factor, factor, detector.focusX, detector.focusY)\\n                imgCanvas?.imageMatrix = matrix\\n                return true\\n            }\\n        })\\n\\n        imgCanvas?.setOnTouchListener { view, event ->\\n            view?.parent?.requestDisallowInterceptTouchEvent(true)\\n\\n            scaleDetector?.onTouchEvent(event)\\n            if (scaleDetector?.isInProgress == false) {\\n                when (event.action) {\\n                    MotionEvent.ACTION_DOWN -> {\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                    MotionEvent.ACTION_MOVE -> {\\n                        val dx = event.x - lastTouchX\\n                        val dy = event.y - lastTouchY\\n                        matrix.postTranslate(dx, dy)\\n                        imgCanvas?.imageMatrix = matrix\\n                        lastTouchX = event.x\\n                        lastTouchY = event.y\\n                    }\\n                    MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {\\n                        view?.parent?.requestDisallowInterceptTouchEvent(false)\\n                    }\\n                }\\n            }\\n            true\\n        }\\n\\n        btnCalcular?.setOnClickListener {\\n            val textoDigitado = edtProblema?.text?.toString() ?: \\"\\"\\n            val moduloSelecionado = edtSeletorModulo?.text?.toString() ?: \\"Espa\\u00e7o Amostral Discreto\\"\\n            \\n            resolverProblemaTextoInteligente(textoDigitado, moduloSelecionado, txtResultado, imgCanvas, txtTituloApp)\\n\\n            imgCanvas?.post {\\n                val vWidth = imgCanvas?.width?.toFloat() ?: 0f\\n                val vHeight = imgCanvas?.height?.toFloat() ?: 0f\\n                val bWidth = 900f \\n                val bHeight = 800f \\n\\n                if (vWidth > 0f && vHeight > 0f) {\\n                    scaleFactor = Math.min(vWidth / bWidth, vHeight / bHeight)\\n                    matrix.reset()\\n                    matrix.postScale(scaleFactor, scaleFactor)\\n                    \\n                    val dx = (vWidth - (bWidth * scaleFactor)) / 2f\\n                    val dy = (vHeight - (bHeight * scaleFactor)) / 2f\\n                    matrix.postTranslate(dx, dy)\\n                    \\n                    imgCanvas?.imageMatrix = matrix\\n                }\\n            }\\n        }\\n\\n        val exemploInicial = \\"Qual a probabilidade de ao lan\\u00e7ar 2 dados obter uma soma igual a 7?\\"\\n        edtProblema?.setText(exemploInicial)\\n    }\\n\\n    private fun isConexaoInternetDisponivel(): Boolean {\\n        val connectivityManager = getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager\\n        val network = connectivityManager.activeNetwork ?: return false\\n        val capabilities = connectivityManager.getNetworkCapabilities(network) ?: return false\\n        return capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)\\n    }\\n\\n    private suspend fun requisitarGroqRender(textoBruto: String, moduloSelecionado: String): String? {\\n        return withContext(Dispatchers.IO) {\\n            try {\\n                val url = URL(\\"https://isaacplot-backend.onrender.com/parsear\\")\\n                val conn = url.openConnection() as HttpURLConnection\\n                conn.requestMethod = \\"POST\\"\\n                conn.setRequestProperty(\\"Content-Type\\", \\"application/json; charset=utf-8\\")\\n                conn.setRequestProperty(\\"Accept\\", \\"application/json\\")\\n                conn.doOutput = true\\n\\n                val jsonInput = JSONObject().apply {\\n                    put(\\"str\\", textoBruto)\\n                    put(\\"modulo\\", moduloSelecionado)\\n                }\\n\\n                conn.outputStream.use { os ->\\n                    val input = jsonInput.toString().toByteArray(Charsets.UTF_8)\\n                    os.write(input, 0, input.size)\\n                }\\n\\n                if (conn.responseCode == 200) {\\n                    val resposta = conn.inputStream.bufferedReader().use { it.readText() }\\n                    val jsonResponse = JSONObject(resposta)\\n                    if (jsonResponse.getBoolean(\\"sucesso\\")) {\\n                        return@withContext jsonResponse.getJSONObject(\\"dados\\").toString()\\n                    }\\n                }\\n                null\\n            } catch (and: Exception) {\\n                and.printStackTrace()\\n                null\\n            }\\n        }\\n    }\\n\\n    private fun resolverProblemaTextoInteligente(str: String, moduloSelecionado: String, txtResultado: TextView?, imgCanvas: ImageView?, txtTituloApp: TextView?) {\\n        txtTituloApp?.text = moduloSelecionado\\n\\n        if (isConexaoInternetDisponivel()) {\\n            txtResultado?.text = \\"Processando com intelig\\u00eancia avan\\u00e7ada (Groq/Render)...\\"\\n            lifecycleScope.launch {\\n                val jsonNuvem = requisitarGroqRender(str, moduloSelecionado)\\n                if (jsonNuvem != null) {\\n                    processarResultadoNuvem(jsonNuvem, moduloSelecionado, txtResultado, imgCanvas)\\n                } else {\\n                    executarCalculoLocal(str, moduloSelecionado, txtResultado, imgCanvas)\\n                }\\n            }\\n        } else {\\n            executarCalculoLocal(str, moduloSelecionado, txtResultado, imgCanvas)\\n        }\\n    }\\n\\n    private fun executarCalculoLocal(str: String, moduloSelecionado: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        var textoFormatado = str.lowercase()\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\b(dois)\\\\\\\\b\\"), \\"2\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\b(tr\\u00eas|tres)\\\\\\\\b\\"), \\"3\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bquatro\\\\\\\\b\\"), \\"4\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bcinco\\\\\\\\b\\"), \\"5\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bseis\\\\\\\\b\\"), \\"6\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bsete\\\\\\\\b\\"), \\"7\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\boito\\\\\\\\b\\"), \\"8\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bnove\\\\\\\\b\\"), \\"9\\")\\n        textoFormatado = textoFormatado.replace(Regex(\\"\\\\\\\\bdez\\\\\\\\b\\"), \\"10\\")\\n\\n        try {\\n            when (moduloSelecionado) {\\n                \\"Distribui\\u00e7\\u00e3o Normal (Gaussiana)\\" -> resolverProbabilidadeGaussiana(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Distribui\\u00e7\\u00e3o Binomial\\" -> resolverBinomialUniversal(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Distribui\\u00e7\\u00e3o de Poisson\\" -> resolverPoissonUniversal(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Teorema de Bayes\\" -> resolverTeoremaDeBayes(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Probabilidade Condicional\\" -> resolverProbabilidadeCondicionalConjuntos(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"An\\u00e1lise Combinat\\u00f3ria\\" -> resolverCombinatoriaPura(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Bin\\u00f4mio de Newton\\" -> resolverBinomioNewton(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                \\"Cadeias de Markov\\" -> resolverProcessoEstocastico(textoFormatado, txtResultado, imgCanvas)\\n                \\"Espa\\u00e7o Amostral Discreto\\" -> resolverProbabilidadeDiscretaAvancada(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n                else -> resolverProbabilidadeDiscretaAvancada(textoFormatado, textoFormatado, txtResultado, imgCanvas)\\n            }\\n        } catch (and: Exception) {\\n            txtResultado?.text = \\"Erro ao processar c\\u00e1lculo: \${and.message}\\"\\n        }\\n    }\\n\\n    private fun processarResultadoNuvem(jsonStr: String, moduloSelecionado: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        try {\\n            val json = JSONObject(jsonStr)\\n            when (moduloSelecionado) {\\n                \\"Distribui\\u00e7\\u00e3o Normal (Gaussiana)\\" -> {\\n                    val m = json.optDouble(\\"media\\", 500.0)\\n                    val dp = json.optDouble(\\"desvio\\", 3.2)\\n                    val x = json.optDouble(\\"x\\", 495.0)\\n                    val maior = json.optBoolean(\\"ehMaior\\", false)\\n                    val tSint = \\"media \$m desvio \$dp x \$x \${if (maior) \\"maior\\" else \\"menor\\"}\\"\\n                    resolverProbabilidadeGaussiana(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Distribui\\u00e7\\u00e3o Binomial\\" -> {\\n                    val n = json.optInt(\\"n\\", 10)\\n                    val k = json.optInt(\\"k\\", 3)\\n                    val p = json.optDouble(\\"p\\", 0.5)\\n                    val tSint = \\"ensaios \$n sucessos \$k probabilidade \$p\\"\\n                    resolverBinomialUniversal(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Distribui\\u00e7\\u00e3o de Poisson\\" -> {\\n                    val lambda = json.optDouble(\\"lambda\\", 3.0)\\n                    val k = json.optInt(\\"k\\", 1)\\n                    val tSint = \\"taxa \$lambda exatamente \$k\\"\\n                    resolverPoissonUniversal(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Teorema de Bayes\\" -> {\\n                    val pA1 = json.optDouble(\\"pA1\\", 0.4)\\n                    val pA2 = json.optDouble(\\"pA2\\", 0.6)\\n                    val pBA1 = json.optDouble(\\"pBA1\\", 0.05)\\n                    val pBA2 = json.optDouble(\\"pBA2\\", 0.02)\\n                    val tSint = \\"maquina a \$pA1 maquina b \$pA2 defeito a \$pBA1 defeito b \$pBA2\\"\\n                    resolverTeoremaDeBayes(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Probabilidade Condicional\\" -> {\\n                    val total = json.optDouble(\\"total\\", 100.0)\\n                    val inter = json.optDouble(\\"inter\\", 20.0)\\n                    val cond = json.optDouble(\\"condicao\\", 50.0)\\n                    val tSint = \\"total \$total ambas \$inter dado que \$cond\\"\\n                    resolverProbabilidadeCondicionalConjuntos(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"An\\u00e1lise Combinat\\u00f3ria\\" -> {\\n                    val n = json.optInt(\\"n\\", 5)\\n                    val k = json.optInt(\\"k\\", 2)\\n                    val type = json.optString(\\"type\\", \\"Combinacao\\")\\n                    val tSint = \\"\$type total \$n tomados \$k\\"\\n                    resolverCombinatoriaPura(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Bin\\u00f4mio de Newton\\" -> {\\n                    val n = json.optInt(\\"n\\", 5)\\n                    val termo = json.optInt(\\"termo\\", 3)\\n                    val tSint = \\"grau \$n termo \$termo\\"\\n                    resolverBinomioNewton(tSint, tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Cadeias de Markov\\" -> {\\n                    val p11 = json.optDouble(\\"p11\\", 0.8)\\n                    val p12 = json.optDouble(\\"p12\\", 0.2)\\n                    val p21 = json.optDouble(\\"p21\\", 0.4)\\n                    val p22 = json.optDouble(\\"p22\\", 0.6)\\n                    val passos = json.optInt(\\"nPassos\\", 2)\\n                    val tSint = \\"continue \$p11 sol for chuva \$p12 chuva for sol \$p21 continue chuvoso \$p22 passos \$passos\\"\\n                    resolverProcessoEstocastico(tSint, txtResultado, imgCanvas)\\n                }\\n                \\"Espa\\u00e7o Amostral Discreto\\" -> {\\n                    val qtd = json.optInt(\\"quantidade\\", 2)\\n                    val alvo = json.optDouble(\\"alvo\\", 7.0)\\n                    val tipoSistema = json.optString(\\"tipoSistema\\", \\"dado\\")\\n                    val totalElementos = json.optInt(\\"total_elementos\\", 0)\\n                    val alvosDisponiveis = json.optInt(\\"alvos_disponiveis\\", 0)\\n                    resolverDiscretoDireto(qtd, alvo, tipoSistema, totalElementos, alvosDisponiveis, txtResultado, imgCanvas)\\n                }\\n                else -> {\\n                    resolverProbabilidadeDiscretaAvancada(\\"\\", \\"\\", txtResultado, imgCanvas)\\n                }\\n            }\\n        } catch (and: Exception) {\\n            txtResultado?.text = \\"Erro ao interpretar resposta da nuvem: \${and.message}\\"\\n        }\\n    }\\n\\n    private fun exibirHtmlFormatado(txtResultado: TextView?, htmlContent: String) {\\n        if (txtResultado != null) {\\n            txtResultado?.text = HtmlCompat.fromHtml(htmlContent, HtmlCompat.FROM_HTML_MODE_COMPACT)\\n        }\\n    }\\n\\n    private fun resolverDiscretoDireto(quantidadeItens: Int, alvo: Double, tipoSistema: String, totalElementos: Int = 0, alvosDisponiveis: Int = 0, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val casosFavoraveis: Double\\n        val totalEspacoAmostral: Double\\n        val sistemaStr: String\\n\\n        \\n        if (totalElementos > 0) {\\n            sistemaStr = \\"\${tipoSistema.uppercase()} (\${totalElementos} itens)\\"\\n            \\n            \\n            totalEspacoAmostral = combinacao(totalElementos, quantidadeItens)\\n            \\n            val alvosDesejados = alvo.toInt()\\n            val restantesNoAmbiente = totalElementos - alvosDisponiveis\\n            val restantesAExtrair = quantidadeItens - alvosDesejados\\n            \\n            \\n            casosFavoraveis = if (alvosDesejados <= alvosDisponiveis && restantesAExtrair <= restantesNoAmbiente && restantesAExtrair >= 0) {\\n                combinacao(alvosDisponiveis, alvosDesejados) * combinacao(restantesNoAmbiente, restantesAExtrair)\\n            } else {\\n                0.0\\n            }\\n        } else {\\n            \\n            val isMoeda = tipoSistema.contains(\\"moeda\\", true)\\n            val faces = if (isMoeda) 2 else 6\\n            sistemaStr = \\"Lan\\u00e7amento de \${quantidadeItens} \${if (faces == 2) \\"moedas\\" else \\"dados\\"}\\"\\n            totalEspacoAmostral = faces.toDouble().pow(quantidadeItens.toDouble())\\n            \\n            val resultadoSimulacao = simularRecursivoAvancado(quantidadeItens, faces, null) { valores ->\\n                if (isMoeda) {\\n                    \\n                    val qtdCaras = valores.count { it == 1 }.toDouble()\\n                    qtdCaras == alvo\\n                } else {\\n                    \\n                    val metrica = if (quantidadeItens == 1) valores[0].toDouble() else valores.sum().toDouble()\\n                    metrica == alvo\\n                }\\n            }\\n            casosFavoraveis = resultadoSimulacao.first.toDouble()\\n        }\\n        \\n        val probabilidade = if (totalEspacoAmostral > 0) (casosFavoraveis / totalEspacoAmostral) * 100.0 else 0.0\\n        \\n        val favStr = casosFavoraveis.toLong().toString()\\n        val totalStr = totalEspacoAmostral.toLong().toString()\\n        val probStr = String.format(\\"%.2f\\", probabilidade)\\n\\n        val html = \\"\\"\\"\\n            <b>ESPA\\u00c7O AMOSTRAL DISCRETO (INTELIGENTE)</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Sistema: \${sistemaStr}<br>\\n            Alvo Buscado: \${alvo.toInt()}<br><br>\\n            <b>Resolu\\u00e7\\u00e3o Direta via Nuvem:</b><br>\\n            \\u2022 Casos Favor\\u00e1veis: \${favStr}<br>\\n            \\u2022 Total do Espa\\u00e7o Amostral: \${totalStr}<br><br>\\n            C\\u00e1lculo: P = \${favStr} / \${totalStr}<br><br>\\n            \\u2794 <b>Probabilidade Final:</b> <b>\${probStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(casosFavoraveis, totalEspacoAmostral, \\"Favor\\u00e1veis\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverProcessoEstocastico(str: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        val p11 = if (numeros.isNotEmpty()) (if (numeros[0] > 1.0) numeros[0] / 100.0 else numeros[0]) else 0.7\\n        val p12 = if (numeros.size > 1) (if (numeros[1] > 1.0) numeros[1] / 100.0 else numeros[1]) else 0.3\\n        val p21 = if (numeros.size > 2) (if (numeros[2] > 1.0) numeros[2] / 100.0 else numeros[2]) else 0.4\\n        val p22 = if (numeros.size > 3) (if (numeros[3] > 1.0) numeros[3] / 100.0 else numeros[3]) else 0.6\\n        val n = if (numeros.size > 4) numeros[4].toInt() else 2\\n\\n        var v1 = 1.0\\n        var v2 = 0.0\\n\\n        val passosDetalhados = StringBuilder()\\n        passosDetalhados.append(\\"<b>Passo a Passo da Evolu\\u00e7\\u00e3o Estoc\\u00e1stica:</b><br>\\")\\n        for (i in 1..n) {\\n            val novoV1 = v1 * p11 + v2 * p21\\n            val novoV2 = v1 * p12 + v2 * p22\\n            val strV1 = String.format(\\"%.4f\\", novoV1)\\n            val strV2 = String.format(\\"%.4f\\", novoV2)\\n            passosDetalhados.append(\\"\\u2022 Passo \${i}: v<sub>\${i}</sub> = [\${strV1} , \${strV2}]<br>\\")\\n            v1 = novoV1\\n            v2 = novoV2\\n        }\\n\\n        val htmlP11 = String.format(\\"%.2f\\", p11)\\n        val htmlP12 = String.format(\\"%.2f\\", p12)\\n        val htmlP21 = String.format(\\"%.2f\\", p21)\\n        val htmlP22 = String.format(\\"%.2f\\", p22)\\n        val probA = String.format(\\"%.2f\\", v1 * 100.0)\\n        val probB = String.format(\\"%.2f\\", v2 * 100.0)\\n\\n        val html = \\"\\"\\"\\n            <b>CADEIAS DE MARKOV (2 Estados)</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            <b>Matriz de Transi\\u00e7\\u00e3o (P):</b><br>\\n            &nbsp;&nbsp;| \${htmlP11} &nbsp;&nbsp; \${htmlP12} |<br>\\n            &nbsp;&nbsp;| \${htmlP21} &nbsp;&nbsp; \${htmlP22} |<br><br>\\n            Estado Inicial: v<sub>0</sub> = [1.00 , 0.00] | Passos: <b>\${n}</b><br>\\n            Equa\\u00e7\\u00e3o iterativa: v<sup>(k)</sup> = v<sup>(k-1)</sup> \\u00b7 P<br><br>\\n            \${passosDetalhados}<br>\\n            \\u2794 <b>Prob. Final Estado A:</b> \${probA}%<br>\\n            \\u2794 <b>Prob. Final Estado B:</b> \${probB}%\\n        \\"\\"\\".trimIndent()\\n        \\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(v1 * 100.0, 100.0, \\"Prob. Estado A\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverBinomioNewton(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        var n: Int? = null\\n        for (match in matchResults) {\\n            val numVal = match.value.toInt()\\n            val startIdx = match.range.first\\n            val subContexto = textoLower.substring(Math.max(0, startIdx - 25), startIdx)\\n            if (subContexto.contains(\\"grau\\") || subContexto.contains(\\"elevado\\") || subContexto.contains(\\"expoente\\")) {\\n                n = numVal\\n                break\\n            }\\n        }\\n        if (n == null) {\\n            n = numeros.filter { it > 1.0 }.maxOrNull()?.toInt() ?: numeros.firstOrNull()?.toInt() ?: 5\\n        }\\n\\n        val termoTexto = when {\\n            textoLower.contains(\\"primeiro\\") -> 1\\n            textoLower.contains(\\"segundo\\") -> 2\\n            textoLower.contains(\\"terceiro\\") -> 3\\n            textoLower.contains(\\"quarto\\") -> 4\\n            textoLower.contains(\\"quinto\\") -> 5\\n            textoLower.contains(\\"sexto\\") -> 6\\n            textoLower.contains(\\"s\\u00e9timo\\") || textoLower.contains(\\"setimo\\") -> 7\\n            textoLower.contains(\\"oitavo\\") -> 8\\n            textoLower.contains(\\"nono\\") -> 9\\n            textoLower.contains(\\"d\\u00e9cimo\\") || textoLower.contains(\\"decimo\\") -> 10\\n            else -> null\\n        }\\n\\n        var termoPedido = termoTexto\\n        if (termoPedido == null) {\\n            for (match in matchResults) {\\n                val numVal = match.value.toInt()\\n                val startIdx = match.range.first\\n                val subContexto = textoLower.substring(Math.max(0, startIdx - 25), startIdx)\\n                if (subContexto.contains(\\"termo\\")) {\\n                    termoPedido = numVal\\n                    break\\n                }\\n            }\\n        }\\n        if (termoPedido == null) {\\n            val restantes = numeros.map { it.toInt() }.filter { it != n }\\n            termoPedido = restantes.firstOrNull() ?: 3\\n        }\\n\\n        val k = if (termoPedido > 0) termoPedido - 1 else 0\\n        val coeficiente = combinacao(n, k)\\n\\n        val nomeTermo = when (termoPedido) {\\n            1 -> \\"primeiro termo\\"\\n            2 -> \\"segundo termo\\"\\n            3 -> \\"terceiro termo\\"\\n            4 -> \\"quarto termo\\"\\n            5 -> \\"quinto termo\\"\\n            6 -> \\"sexto termo\\"\\n            7 -> \\"s\\u00e9timo termo\\"\\n            8 -> \\"oitavo termo\\"\\n            9 -> \\"nono termo\\"\\n            10 -> \\"d\\u00e9cimo termo\\"\\n            else -> \\"termo \${termoPedido}\\"\\n        }\\n\\n        val nFat = fatorial(n).toLong()\\n        val kFat = fatorial(k).toLong()\\n        val nMinK = n - k\\n        val nMinKFat = fatorial(nMinK).toLong()\\n        val coefStr = coeficiente.toLong().toString()\\n        val kPlus1 = k + 1\\n\\n        val html = \\"\\"\\"\\n            <b>BIN\\u00d4MIO DE NEWTON</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Forma: (x + y)<sup>\${n}</sup> | Grau n = \${n}<br>\\n            Termo Desejado: <b>\${nomeTermo}</b> (\\u00edndice k = \${k})<br><br>\\n            <b>F\\u00f3rmula Detalhada do Termo Geral:</b><br>\\n            T<sub>k+1</sub> = C(n, k) \\u00b7 x<sup>n-k</sup> \\u00b7 y<sup>k</sup><br>\\n            T<sub>\${kPlus1}</sub> = C(\${n}, \${k}) \\u00b7 x<sup>\${n}-\${k}</sup> \\u00b7 y<sup>\${k}</sup><br><br>\\n            <b>Detalhamento do Coeficiente Binomial:</b><br>\\n            \\u2022 Fatorial de n: \${n}! = \${nFat}<br>\\n            \\u2022 Fatorial de k: \${k}! = \${kFat}<br>\\n            \\u2022 Fatorial de (n - k): (\${n} - \${k})! = \${nMinKFat}<br><br>\\n            C\\u00e1lculo:<br>\\n            &nbsp;&nbsp;<u>&nbsp;&nbsp;<b>\${n}!</b>&nbsp;&nbsp;</u><br>\\n            &nbsp;&nbsp;<b>\${k}! \\u00b7 (\${nMinK})!</b><br><br>\\n            \\u2794 <b>Coeficiente Final C(\${n},\${k}):</b> <b>\${coefStr}</b>\\n        \\"\\"\\".trimIndent()\\n        \\n        exibirHtmlFormatado(txtResultado, html)\\n\\n        val bitmap = Bitmap.createBitmap(900, 800, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n        val paint = Paint().apply { color = Color.parseColor(\\"#334155\\"); textSize = 40f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n        canvas.drawText(\\"Coeficiente: \${coefStr}\\", 450f, 400f, paint)\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverCombinatoriaPura(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        val n = numeros.maxOrNull()?.toInt() ?: 5\\n        val k = if (numeros.size > 1) {\\n            numeros.filter { it.toInt() != n }.minOrNull()?.toInt() ?: n\\n        } else {\\n            n\\n        }\\n\\n        val resultadoCombinatorio: Double\\n        val formulaHtml: String\\n        val nome: String\\n        \\n        val nFat = fatorial(n).toLong()\\n        val kFat = fatorial(k).toLong()\\n        val nMinK = n - k\\n        val nMinKFat = fatorial(nMinK).toLong()\\n\\n        if (textoLower.contains(\\"arranjo\\") || textoLower.contains(\\"senhas\\")) {\\n            nome = \\"Arranjo Simples\\"\\n            formulaHtml = \\"A(\${n},\${k}) = n! / (n - k)! = \${n}! / (\${n} - \${k})!<br>Fatores calculados passo a passo.\\"\\n            resultadoCombinatorio = if (n >= k) fatorial(n) / fatorial(n - k) else 0.0\\n        } else if (textoLower.contains(\\"permuta\\u00e7\\u00e3o\\") || textoLower.contains(\\"permutacao\\") || textoLower.contains(\\"anagrama\\")) {\\n            nome = \\"Permuta\\u00e7\\u00e3o Simples\\"\\n            formulaHtml = \\"P(\${n}) = \${n}! = \${nFat}\\"\\n            resultadoCombinatorio = fatorial(n)\\n        } else {\\n            nome = \\"Combina\\u00e7\\u00e3o Simples\\"\\n            formulaHtml = \\"C(\${n},\${k}) = n! / [k! \\u00b7 (n - k)!]<br>C(\${n},\${k}) = \${n}! / [\${k}! \\u00b7 (\${n} - \${k})!]\\"\\n            resultadoCombinatorio = combinacao(n, k)\\n        }\\n        \\n        val resultadoStr = resultadoCombinatorio.toLong().toString()\\n\\n        val html = \\"\\"\\"\\n            <b>AN\\u00c1LISE COMBINAT\\u00d3RIA</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Tipo Identificado: <b>\${nome}</b><br>\\n            Par\\u00e2metros: n = \${n} | k = \${k}<br><br>\\n            <b>Resolu\\u00e7\\u00e3o Passo a Passo:</b><br>\\n            \${formulaHtml}<br>\\n            \\u2022 Fatorial de n (\${n}!): \${nFat}<br>\\n            \\u2022 Fatorial de k (\${k}!): \${kFat}<br>\\n            \\u2022 Fatorial da diferen\\u00e7a (\${nMinK}!): \${nMinKFat}<br><br>\\n            \\u2794 <b>Total de Formas Poss\\u00edveis:</b> <b>\${resultadoStr}</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n\\n        val bitmap = Bitmap.createBitmap(900, 800, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n        val paint = Paint().apply { color = Color.parseColor(\\"#2563EB\\"); textSize = 50f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n        canvas.drawText(String.format(\\"Total = %.0f\\", resultadoCombinatorio), 450f, 400f, paint)\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverPoissonUniversal(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        var lambda: Double? = null\\n        var k: Int? = null\\n\\n        for (match in matchResults) {\\n            val numVal = match.value.toDouble()\\n            val startIdx = match.range.first\\n            val subContexto = textoLower.substring(Math.max(0, startIdx - 30), startIdx)\\n            if ((subContexto.contains(\\"taxa\\") || subContexto.contains(\\"m\\u00e9dia\\") || subContexto.contains(\\"media\\")) && lambda == null) {\\n                lambda = numVal\\n            } else if ((subContexto.contains(\\"exatamente\\") || subContexto.contains(\\"vezes\\") || subContexto.contains(\\"chamadas\\") || subContexto.contains(\\"acidente\\") || subContexto.contains(\\"acontecer\\")) && k == null) {\\n                k = numVal.toInt()\\n            }\\n        }\\n\\n        val lambdaFinal = lambda ?: numeros.getOrNull(0) ?: 3.0\\n        val kFinal = k ?: numeros.filter { it != lambdaFinal }.firstOrNull()?.toInt() ?: 1\\n\\n        val euler = exp(-lambdaFinal)\\n        val lambdaPow = lambdaFinal.pow(kFinal.toDouble())\\n        val fatK = fatorial(kFinal)\\n        val pPoisson = (euler * lambdaPow) / fatK\\n        val percentual = pPoisson * 100.0\\n        \\n        val eulerStr = String.format(\\"%.5f\\", euler)\\n        val lambdaPowStr = String.format(\\"%.4f\\", lambdaPow)\\n        val fatKStr = fatK.toLong().toString()\\n        val numeradorStr = String.format(\\"%.5f\\", euler * lambdaPow)\\n        val pPoissonStr = String.format(\\"%.5f\\", pPoisson)\\n        val percentualStr = String.format(\\"%.2f\\", percentual)\\n\\n        val html = \\"\\"\\"\\n            <b>DISTRIBUI\\u00c7\\u00c3O DE POISSON</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Taxa M\\u00e9dia (\\u03bb) = \${lambdaFinal} | Ocorr\\u00eancias desejadas (k) = \${kFinal}<br><br>\\n            <b>F\\u00f3rmula Geral Detalhada:</b><br>\\n            P(X = k) = (and<sup>-\\u03bb</sup> \\u00b7 \\u03bb<sup>k</sup>) / k!<br><br>\\n            <b>Passo a Passo Completo:</b><br>\\n            1) Constante de Euler and<sup>-\${lambdaFinal}</sup> \\u2248 \${eulerStr}<br>\\n            2) Pot\\u00eancia da taxa \${lambdaFinal}<sup>\${kFinal}</sup> = \${lambdaPowStr}<br>\\n            3) Fatorial do n\\u00famero de ocorr\\u00eancias \${kFinal}! = \${fatKStr}<br>\\n            4) Multiplica\\u00e7\\u00e3o do numerador: \${numeradorStr}<br>\\n            5) Divis\\u00e3o pelo denominador (\${fatKStr}): \${pPoissonStr}<br><br>\\n            \\u2794 <b>Probabilidade Final:</b> <b>\${percentualStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(percentual, 100.0, \\"Probabilidade\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverBinomialUniversal(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        var n = 10\\n        var k = 3\\n        var p = 0.5\\n\\n        if (textoLower.contains(\\"alternativas\\")) {\\n            val alternativas = numeros.find { it in 2.0..10.0 } ?: 4.0\\n            p = 1.0 / alternativas\\n            val restantes = numeros.filter { it != alternativas }\\n            n = restantes.maxOrNull()?.toInt() ?: 5\\n            k = restantes.minOrNull()?.toInt() ?: 2\\n        } else {\\n            val pMatch = numeros.find { (it > 0.0 && it < 1.0) || (it > 1.0 && it < 100.0 && textoLower.contains(\\"%\\")) }\\n            if (pMatch != null) {\\n                p = if (pMatch > 1.0) pMatch / 100.0 else pMatch\\n                val restantes = numeros.filter { it != pMatch }\\n                if (restantes.size >= 2) {\\n                    n = restantes.maxOrNull()?.toInt() ?: 10\\n                    k = restantes.minOrNull()?.toInt() ?: 3\\n                } else if (restantes.size == 1) {\\n                    n = restantes[0].toInt()\\n                }\\n            } else if (numeros.size >= 2) {\\n                n = numeros.maxOrNull()?.toInt() ?: 10\\n                k = numeros.minOrNull()?.toInt() ?: 3\\n            }\\n        }\\n        \\n        if (p > 1.0) p /= 100.0\\n        val q = 1.0 - p\\n\\n        val comb = combinacao(n, k)\\n        val pSucesso = p.pow(k.toDouble())\\n        val pFracasso = q.pow((n - k).toDouble())\\n        val pBinomial = comb * pSucesso * pFracasso\\n        val percentual = pBinomial * 100.0\\n        \\n        val combStr = comb.toLong().toString()\\n        val pSucessoStr = String.format(\\"%.5f\\", pSucesso)\\n        val pFracassoStr = String.format(\\"%.5f\\", pFracasso)\\n        val percentualStr = String.format(\\"%.2f\\", percentual)\\n        val nMinK = n - k\\n\\n        val html = \\"\\"\\"\\n            <b>DISTRIBUI\\u00c7\\u00c3O BINOMIAL</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Ensaios (n) = \${n} | Sucessos (k) = \${k} | Prob. Sucesso (p) = \${p} | Prob. Fracasso (q) = \${q}<br><br>\\n            <b>F\\u00f3rmula de Bernoulli Detalhada:</b><br>\\n            P(X = k) = C(n, k) \\u00b7 p<sup>k</sup> \\u00b7 q<sup>n-k</sup><br><br>\\n            <b>Passo a Passo Completo:</b><br>\\n            1) Combina\\u00e7\\u00e3o C(\${n}, \${k}) = \${combStr}<br>\\n            2) Probabilidade de sucessos p<sup>\${k}</sup> \\u2248 \${pSucessoStr}<br>\\n            3) Probabilidade de fracassos q<sup>\${nMinK}</sup> \\u2248 \${pFracassoStr}<br>\\n            4) Produto dos termos: \${combStr} \\u00b7 \${pSucessoStr} \\u00b7 \${pFracassoStr}<br><br>\\n            \\u2794 <b>Probabilidade Final:</b> <b>\${percentualStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(percentual, 100.0, \\"Probabilidade\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n    \\n    private fun resolverProbabilidadeCondicionalConjuntos(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }.distinct()\\n\\n        if (numeros.size < 3) {\\n            txtResultado?.text = \\"Erro: O problema precisa conter 3 n\\u00fameros (Total, Intersec\\u00e7\\u00e3o and Condi\\u00e7\\u00e3o).\\"\\n            return\\n        }\\n\\n        val totalAlunos = numeros.maxOrNull() ?: return\\n        val subconjuntos = numeros.filter { it != totalAlunos }.sorted()\\n\\n        val nInterFinal = subconjuntos.getOrNull(0) ?: return\\n        val nCondicaoFinal = subconjuntos.getOrNull(1) ?: return\\n\\n        val prob = if (nCondicaoFinal > 0) nInterFinal / nCondicaoFinal else 0.0\\n        val percentual = prob * 100.0\\n\\n        val interStr = String.format(\\"%.0f\\", nInterFinal)\\n        val condStr = String.format(\\"%.0f\\", nCondicaoFinal)\\n        val totalStr = String.format(\\"%.0f\\", totalAlunos)\\n        val probStr = String.format(\\"%.2f\\", percentual)\\n\\n        val html = \\"\\"\\"\\n            <b>PROBABILIDADE CONDICIONAL (CONJUNTOS)</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Total do Espa\\u00e7o Amostral (N) = \${totalStr}<br>\\n            Intersec\\u00e7\\u00e3o (Ambas) = \${interStr} | Condi\\u00e7\\u00e3o (Dado que) = \${condStr}<br><br>\\n            <b>F\\u00f3rmula da Probabilidade Condicional:</b><br>\\n            P(B | A) = n(A \\u2229 B) / n(A)<br><br>\\n            <b>Passo a Passo Detalhado:</b><br>\\n            1) Casos favor\\u00e1veis (intersec\\u00e7\\u00e3o): \${interStr}<br>\\n            2) Espa\\u00e7o amostral reduzido (condi\\u00e7\\u00e3o): \${condStr}<br>\\n            3) Divis\\u00e3o: \${interStr} / \${condStr} = \${String.format(\\"%.4f\\", prob)}<br><br>\\n            \\u2794 <b>Probabilidade Final:</b> <b>\${probStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(percentual, 100.0, \\"Condicional\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverTeoremaDeBayes(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        val pA1 = if (numeros.isNotEmpty()) (if (numeros[0] > 1.0) numeros[0] / 100.0 else numeros[0]) else 0.2\\n        val pA2 = if (numeros.size > 1) (if (numeros[1] > 1.0) numeros[1] / 100.0 else numeros[1]) else 0.8\\n        val pBA1 = if (numeros.size > 2) (if (numeros[2] > 1.0) numeros[2] / 100.0 else numeros[2]) else 0.95\\n        val pBA2 = if (numeros.size > 3) (if (numeros[3] > 1.0) numeros[3] / 100.0 else numeros[3]) else 0.10\\n\\n        val interA1 = pA1 * pBA1\\n        val interA2 = pA2 * pBA2\\n        val pB = interA1 + interA2\\n        val pA1GivenB = if (pB > 0) interA1 / pB else 0.0\\n        val probabilidadePercentual = pA1GivenB * 100.0\\n        \\n        val interA1Str = String.format(\\"%.4f\\", interA1)\\n        val interA2Str = String.format(\\"%.4f\\", interA2)\\n        val pBStr = String.format(\\"%.4f\\", pB)\\n        val probPosterioriStr = String.format(\\"%.2f\\", probabilidadePercentual)\\n\\n        val html = \\"\\"\\"\\n            <b>TEOREMA DE BAYES</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            P(A<sub>1</sub>) = \${pA1} | P(A<sub>2</sub>) = \${pA2}<br>\\n            P(B|A<sub>1</sub>) = \${pBA1} | P(B|A<sub>2</sub>) = \${pBA2}<br><br>\\n            <b>Passo a Passo Detalhado:</b><br>\\n            1) Intersec\\u00e7\\u00e3o 1: P(A<sub>1</sub>) \\u00b7 P(B|A<sub>1</sub>) = \${pA1} \\u00b7 \${pBA1} = \${interA1Str}<br>\\n            2) Intersec\\u00e7\\u00e3o 2: P(A<sub>2</sub>) \\u00b7 P(B|A<sub>2</sub>) = \${pA2} \\u00b7 \${pBA2} = \${interA2Str}<br>\\n            3) Probabilidade Total P(B) = \${interA1Str} + \${interA2Str} = <b>\${pBStr}</b><br><br>\\n            <b>F\\u00f3rmula de Bayes P(A<sub>1</sub>|B):</b><br>\\n            &nbsp;&nbsp;<u>P(A<sub>1</sub>) \\u00b7 P(B|A<sub>1</sub>)</u><br>\\n            &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;P(B)<br><br>\\n            \\u2794 <b>Probabilidade A Posteriori:</b> <b>\${probPosterioriStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(pA1GivenB * 100.0, 100.0, \\"A Posteriori\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverProbabilidadeGaussiana(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n\\n        if (matchResults.size < 3) {\\n            txtResultado?.text = \\"Erro: O str cont\\u00ednuo precisa conter pelo menos 3 n\\u00fameros (M\\u00e9dia, Desvio Padr\\u00e3o and o Valor X).\\"\\n            val emptyBitmap = Bitmap.createBitmap(900, 800, Bitmap.Config.ARGB_8888)\\n            val canvas = Canvas(emptyBitmap)\\n            canvas.drawColor(Color.WHITE)\\n            imgCanvas?.setImageBitmap(emptyBitmap)\\n            return\\n        }\\n\\n        val numeros = matchResults.map { it.value.toDouble() }\\n        var media: Double? = null\\n        var desvioPadrao: Double? = null\\n        var x: Double? = null\\n\\n        for (match in matchResults) {\\n            val numVal = match.value.toDouble()\\n            val startIdx = match.range.first\\n            val subContexto = textoLower.substring(Math.max(0, startIdx - 35), startIdx)\\n\\n            if ((subContexto.contains(\\"media\\") || subContexto.contains(\\"mu\\") || subContexto.contains(\\"m\\u00e9dia\\")) && media == null) {\\n                media = numVal\\n            } else if ((subContexto.contains(\\"desvio\\") || subContexto.contains(\\"sigma\\") || subContexto.contains(\\"dp\\")) && desvioPadrao == null) {\\n                desvioPadrao = numVal\\n            } else if ((subContexto.contains(\\"menor\\") || subContexto.contains(\\"maior\\") || subContexto.contains(\\"igual\\") || subContexto.contains(\\"que\\") || subContexto.contains(\\"valor\\") || subContexto.contains(\\"x\\") || subContexto.contains(\\"ml\\") || subContexto.contains(\\"quilos\\") || subContexto.contains(\\"acima\\") || subContexto.contains(\\"abaixo\\")) && x == null) {\\n                x = numVal\\n            }\\n        }\\n\\n        val m = media ?: numeros[0]\\n        val dp = desvioPadrao ?: numeros[1]\\n        val valorX = x ?: numeros.getOrNull(2) ?: numeros.last()\\n\\n        if (dp <= 0) {\\n            txtResultado?.text = \\"Erro: O desvio padr\\u00e3o deve ser estritamente maior que zero.\\"\\n            return\\n        }\\n\\n        val ehMaior = textoLower.contains(\\"maior\\") || textoLower.contains(\\"acima\\") || textoLower.contains(\\"superior\\") || textoLower.contains(\\"mais que\\")\\n\\n        val zScore = (valorX - m) / dp\\n        val cdf = calcularCDFNormal(zScore)\\n        val probabilidade = if (ehMaior) (1.0 - cdf) * 100.0 else cdf * 100.0\\n        val tipoCondicao = if (ehMaior) \\"X \\u2265\\" else \\"X \\u2264\\"\\n        \\n        val diff = valorX - m\\n        val zScoreStr = String.format(\\"%.3f\\", zScore)\\n        val probStr = String.format(\\"%.2f\\", probabilidade)\\n\\n        val html = \\"\\"\\"\\n            <b>DISTRIBUI\\u00c7\\u00c3O NORMAL (GAUSSIANA)</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            M\\u00e9dia (\\u03bc) = \${m} | Desvio Padr\\u00e3o (\\u03c3) = \${dp} | Valor X = \${valorX}<br><br>\\n            <b>Passo a Passo do Escore Z:</b><br>\\n            1) Subtra\\u00e7\\u00e3o da m\\u00e9dia: X - \\u03bc = \${valorX} - \${m} = \${diff}<br>\\n            2) Divis\\u00e3o pelo desvio padr\\u00e3o: Z = (X - \\u03bc) / \\u03c3 = \${diff} / \${dp} = <b>\${zScoreStr}</b><br>\\n            3) Consulta da Fun\\u00e7\\u00e3o de Distribui\\u00e7\\u00e3o Acumulada (CDF) for Z = \${zScoreStr}<br><br>\\n            \\u2794 <b>Probabilidade (\${tipoCondicao} \${valorX}):</b> <b>\${probStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharCurvaGaussiana(m, dp, valorX, ehMaior)\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun resolverProbabilidadeDiscretaAvancada(str: String, textoLower: String, txtResultado: TextView?, imgCanvas: ImageView?) {\\n        val regex = Regex(\\"[-+]?\\\\\\\\d*\\\\\\\\.\\\\\\\\d+|\\\\\\\\d+\\")\\n        val matchResults = regex.findAll(str).toList()\\n        val numeros = matchResults.map { it.value.toDouble() }\\n\\n        val ehMoeda = textoLower.contains(\\"moeda\\") || textoLower.contains(\\"moedas\\") || textoLower.contains(\\"cara\\") || textoLower.contains(\\"coroa\\")\\n        val ehDado = textoLower.contains(\\"dado\\") || textoLower.contains(\\"dados\\")\\n        val ehUrna = textoLower.contains(\\"urna\\") || textoLower.contains(\\"bola\\") || textoLower.contains(\\"bolas\\") || textoLower.contains(\\"balas\\") || textoLower.contains(\\"pedras\\") || textoLower.contains(\\"cartas\\") || textoLower.contains(\\"fichas\\") || textoLower.contains(\\"pe\\u00e7as\\") || textoLower.contains(\\"pessoas\\")\\n\\n        var quantidadeItens = 1\\n        if (!ehUrna) {\\n            for (i in 0 until matchResults.size) {\\n                val num = matchResults[i].value.toInt()\\n                val endIdx = matchResults[i].range.last\\n                val proxContexto = textoLower.substring(endIdx, Math.min(textoLower.length, endIdx + 20))\\n                if (proxContexto.contains(\\"dado\\") || proxContexto.contains(\\"dados\\") || \\n                    proxContexto.contains(\\"moeda\\") || proxContexto.contains(\\"moedas\\")) {\\n                    quantidadeItens = num\\n                    break\\n                }\\n            }\\n        } else {\\n            quantidadeItens = numeros.lastOrNull()?.toInt() ?: 3\\n        }\\n\\n        val alvo = numeros.lastOrNull() ?: 1.0\\n\\n        val temCondicao = textoLower.contains(\\"sabendo\\") || textoLower.contains(\\"dado que\\") || textoLower.contains(\\"constatado\\")\\n        var restricaoPrimeiroItem: Int? = null\\n        if (temCondicao && numeros.size >= 2) {\\n            for (num in numeros) {\\n                if (num in 1.0..6.0 && !num.equals(alvo)) {\\n                    restricaoPrimeiroItem = num.toInt()\\n                    break\\n                }\\n            }\\n        }\\n\\n        val ehMaiorOuIgual = textoLower.contains(\\"maior or igual\\") || textoLower.contains(\\"no m\\u00ednimo\\") || textoLower.contains(\\"ao menos\\") || textoLower.contains(\\"pelo menos\\")\\n        val ehMenorOuIgual = textoLower.contains(\\"menor or igual\\") || textoLower.contains(\\"no m\\u00e1ximo\\") || textoLower.contains(\\"at\\u00e9\\")\\n        val ehMaior = (textoLower.contains(\\"maior\\") || textoLower.contains(\\"acima\\") || textoLower.contains(\\"superior\\") || textoLower.contains(\\"mais que\\")) && !ehMaiorOuIgual\\n        val ehMenor = (textoLower.contains(\\"menor\\") || textoLower.contains(\\"abaixo\\") || textoLower.contains(\\"inferior\\") || textoLower.contains(\\"menos que\\")) && !ehMenorOuIgual\\n\\n        var totalEspacoAmostral = 1.0\\n        var casosFavoraveis = 0.0\\n        val tipoSistema = if (ehMoeda) \\"Lan\\u00e7amento de Moedas\\" else if (ehDado) \\"Lan\\u00e7amento de Dados\\" else \\"Retirada de Urna/Combina\\u00e7\\u00e3o\\"\\n\\n        when {\\n            ehMoeda -> {\\n                val faces = 2\\n                totalEspacoAmostral = faces.toDouble().pow(quantidadeItens.toDouble())\\n                casosFavoraveis = simularRecursivoAvancado(quantidadeItens, faces, restricaoPrimeiroItem, { valores ->\\n                    val qtdCaras = valores.count { it == 1 }.toDouble()\\n                    avaliarCondicao(qtdCaras, alvo, ehMaior, ehMenor, ehMaiorOuIgual, ehMenorOuIgual)\\n                }).first.toDouble()\\n                val espacoReduzido = simularRecursivoAvancado(quantidadeItens, faces, restricaoPrimeiroItem, { _ -> true }).second.toDouble()\\n                if (espacoReduzido > 0) totalEspacoAmostral = espacoReduzido\\n            }\\n            ehDado -> {\\n                val faces = 6\\n                totalEspacoAmostral = faces.toDouble().pow(quantidadeItens.toDouble())\\n                val resultadoSimulacao = simularRecursivoAvancado(quantidadeItens, faces, restricaoPrimeiroItem, { valores ->\\n                    val metrica = if (quantidadeItens == 1) valores[0].toDouble() else valores.sum().toDouble()\\n                    avaliarCondicao(metrica, alvo, ehMaior, ehMenor, ehMaiorOuIgual, ehMenorOuIgual)\\n                })\\n                casosFavoraveis = resultadoSimulacao.first.toDouble()\\n                val espacoReduzido = resultadoSimulacao.second.toDouble()\\n                if (espacoReduzido > 0) {\\n                    totalEspacoAmostral = espacoReduzido\\n                }\\n            }\\n            ehUrna && numeros.size >= 3 -> {\\n                val kRetiradasUrna = quantidadeItens\\n                val cores = numeros.dropLast(1)\\n                val totalBolas = cores.sum().toInt()\\n            \\n                totalEspacoAmostral = combinacao(totalBolas, kRetiradasUrna)\\n                casosFavoraveis = 0.0\\n            \\n                if (textoLower.contains(\\"diferentes\\") || textoLower.contains(\\"distintas\\") || textoLower.contains(\\"uma de cada\\")) {\\n                    var comb = 1.0\\n                    for (qtd in cores) {\\n                        comb *= combinacao(qtd.toInt(), 1)\\n                    }\\n                    casosFavoraveis = comb\\n                } else if (textoLower.contains(\\"mesma\\") || textoLower.contains(\\"iguais\\")) {\\n                    for (qtd in cores) {\\n                        if (qtd >= kRetiradasUrna.toDouble()) {\\n                            casosFavoraveis += combinacao(qtd.toInt(), kRetiradasUrna)\\n                        }\\n                    }\\n                } else {\\n                    casosFavoraveis = if (totalEspacoAmostral > 0) totalEspacoAmostral * 0.5 else 1.0\\n                }\\n            }\\n            else -> {\\n                val nTotal = if (numeros.isNotEmpty()) numeros[0] else 10.0\\n                val kRetiradas = if (numeros.size > 1) numeros[1] else 2.0\\n                totalEspacoAmostral = combinacao(nTotal.toInt(), kRetiradas.toInt())\\n                casosFavoraveis = if (totalEspacoAmostral > 0) totalEspacoAmostral * 0.5 else 1.0\\n            }\\n        }\\n\\n        if (totalEspacoAmostral <= 0) totalEspacoAmostral = 1.0\\n        val probabilidade = (casosFavoraveis / totalEspacoAmostral) * 100.0\\n        \\n        val favStr = casosFavoraveis.toLong().toString()\\n        val totalStr = totalEspacoAmostral.toLong().toString()\\n        val probStr = String.format(\\"%.2f\\", probabilidade)\\n\\n        val html = \\"\\"\\"\\n            <b>ESPA\\u00c7O AMOSTRAL DISCRETO</b><br>\\n            \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500<br>\\n            Sistema: \${tipoSistema}<br>\\n            Quantidade Retirada: \${quantidadeItens} | Cores Mapeadas: \${if (ehUrna && numeros.size >= 3) numeros.dropLast(1).joinToString(\\", \\") else \\"\${quantidadeItens}\\"}<br><br>\\n            <b>Passo a Passo Detalhado (Lei de Laplace):</b><br>\\n            1) Mapeamento completo do espa\\u00e7o amostral gerado.<br>\\n            2) Filtragem dos casos que satisfazem a condi\\u00e7\\u00e3o estabelecida.<br>\\n            \\u2022 Casos Favor\\u00e1veis: \${favStr}<br>\\n            \\u2022 Total do Espa\\u00e7o Amostral: \${totalStr}<br><br>\\n            C\\u00e1lculo: P = \${favStr} / \${totalStr}<br><br>\\n            \\u2794 <b>Probabilidade Final:</b> <b>\${probStr}%</b>\\n        \\"\\"\\".trimIndent()\\n\\n        exibirHtmlFormatado(txtResultado, html)\\n        val bitmap = desenharGraficoBarrasDiscreto(casosFavoraveis, totalEspacoAmostral, \\"Favor\\u00e1veis\\")\\n        imgCanvas?.setImageBitmap(bitmap)\\n    }\\n\\n    private fun simularRecursivoAvancado(n: Int, faces: Int, restricaoFalta: Int?, condicao: (List<Int>) -> Boolean): Pair<Int, Int> {\\n        var favoraveis = 0\\n        var totalValidos = 0\\n\\n        fun rodar(atual: MutableList<Int>) {\\n            if (atual.size == n) {\\n                if (restricaoFalta == null || atual[0] == restricaoFalta) {\\n                    totalValidos++\\n                    if (condicao(atual)) {\\n                        favoraveis++\\n                    }\\n                }\\n                return\\n            }\\n            for (i in 1..faces) {\\n                atual.add(i)\\n                rodar(atual)\\n                atual.removeAt(atual.size - 1)\\n            }\\n        }\\n\\n        rodar(mutableListOf())\\n        return Pair(favoraveis, totalValidos)\\n    }\\n\\n    private fun avaliarCondicao(valor: Double, alvo: Double, ehMaior: Boolean, ehMenor: Boolean, ehMaiorOuIgual: Boolean, ehMenorOuIgual: Boolean): Boolean {\\n        return when {\\n            ehMaior -> valor > alvo\\n            ehMenor -> valor < alvo\\n            ehMaiorOuIgual -> valor >= alvo\\n            ehMenorOuIgual -> valor <= alvo\\n            else -> valor == alvo\\n        }\\n    }\\n\\n    private fun fatorial(n: Int): Double {\\n        if (n <= 1) return 1.0\\n        var fat = 1.0\\n        for (i in 2..n) {\\n            fat *= i.toDouble()\\n        }\\n        return fat\\n    }\\n\\n    private fun combinacao(n: Int, k: Int): Double {\\n        if (k > n || k < 0) return 0.0\\n        return fatorial(n) / (fatorial(k) * fatorial(n - k))\\n    }\\n\\n    private fun calcularCDFNormal(z: Double): Double {\\n        val zMod = Math.abs(z) / Math.sqrt(2.0)\\n        val t = 1.0 / (1.0 + 0.5 * zMod)\\n        val ans = t * exp(-zMod * zMod - 1.26551223 +\\n                t * (1.00002368 + t * (0.37409196 + t * (0.09678418 + t * (-0.18628806 +\\n                t * (0.27886807 + t * (-1.13520398 + t * (1.48851587 +\\n                t * (-0.82215223 + t * 0.17087277)))))))))\\n        val erf = 1.0 - ans\\n        val res = if (z >= 0) erf else -erf\\n        return 0.5 * (1.0 + res)\\n    }\\n\\n    private fun desenharCurvaGaussiana(media: Double, desvioPadrao: Double, valorX: Double, ehMaior: Boolean): Bitmap {\\n        val width = 900\\n        val height = 800\\n        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n\\n        val margin = 80f\\n        val renderWidth = width - 2 * margin\\n        val renderHeight = height - 2 * margin\\n\\n        val minX = media - 4 * desvioPadrao\\n        val maxX = media + 4 * desvioPadrao\\n        val rangeX = maxX - minX\\n\\n        val maxDensity = 1.0 / (desvioPadrao * sqrt(2.0 * Math.PI))\\n\\n        val paintGrid = Paint().apply { color = Color.parseColor(\\"#E2E8F0\\"); strokeWidth = 2f; isAntiAlias = true }\\n        val paintAxis = Paint().apply { color = Color.parseColor(\\"#334155\\"); strokeWidth = 4f; isAntiAlias = true }\\n        val paintGaussLine = Paint().apply { color = Color.parseColor(\\"#DC2626\\"); strokeWidth = 6f; style = Paint.Style.STROKE; isAntiAlias = true }\\n        val paintAreaFill = Paint().apply { color = Color.parseColor(\\"#66DC2626\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n        val paintText = Paint().apply { color = Color.parseColor(\\"#475569\\"); textSize = 20f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n\\n        val yTicks = 5\\n        for (i in 0..yTicks) {\\n            val py = height - margin - (i.toFloat() / yTicks) * renderHeight\\n            canvas.drawLine(margin, py, width - margin, py, paintGrid)\\n        }\\n\\n        canvas.drawLine(margin, height - margin, width - margin, height - margin, paintAxis)\\n        canvas.drawLine(margin, margin, margin, height - margin, paintAxis)\\n\\n        val steps = 300\\n        val pathGauss = Path()\\n        val pathArea = Path()\\n        var startedGauss = false\\n        var startedArea = false\\n\\n        for (s in 0..steps) {\\n            val xData = minX + s * rangeX / steps\\n            val exponent = -0.5 * ((xData - media) / desvioPadrao).pow(2.0)\\n            val pdf = maxDensity * exp(exponent)\\n\\n            val px = margin + ((xData - minX) / rangeX) * renderWidth\\n            val py = height - margin - (pdf / maxDensity) * renderHeight\\n\\n            if (!startedGauss) {\\n                pathGauss.moveTo(px.toFloat(), py.toFloat())\\n                startedGauss = true\\n            } else {\\n                pathGauss.lineTo(px.toFloat(), py.toFloat())\\n            }\\n\\n            val atendeCondicao = if (ehMaior) xData >= valorX else xData <= valorX\\n            if (atendeCondicao) {\\n                if (!startedArea) {\\n                    val startX = if (ehMaior) Math.max(valorX, minX) else minX\\n                    val startPx = margin + ((startX - minX) / rangeX) * renderWidth\\n                    pathArea.moveTo(startPx.toFloat(), height - margin)\\n                    pathArea.lineTo(px.toFloat(), py.toFloat())\\n                    startedArea = true\\n                } else {\\n                    pathArea.lineTo(px.toFloat(), py.toFloat())\\n                }\\n            }\\n        }\\n\\n        if (startedArea) {\\n            val endX = if (ehMaior) maxX else Math.min(valorX, maxX)\\n            val endPx = margin + ((endX - minX) / rangeX) * renderWidth\\n            pathArea.lineTo(endPx.toFloat(), height - margin)\\n            pathArea.close()\\n            canvas.drawPath(pathArea, paintAreaFill)\\n        }\\n\\n        canvas.drawPath(pathGauss, paintGaussLine)\\n\\n        canvas.drawText(String.format(\\"%.1f\\", minX), margin, height - margin + 35f, paintText)\\n        canvas.drawText(String.format(\\"\\u03bc=%.1f\\", media), margin + renderWidth / 2, height - margin + 35f, paintText)\\n        canvas.drawText(String.format(\\"%.1f\\", maxX), width - margin, height - margin + 35f, paintText)\\n\\n        val pxValorX = margin + ((valorX - minX) / rangeX) * renderWidth\\n        if (pxValorX in margin..(width - margin)) {\\n            val paintXLine = Paint().apply { color = Color.parseColor(\\"#2563EB\\"); strokeWidth = 3f; style = Paint.Style.STROKE; isAntiAlias = true }\\n            canvas.drawLine(pxValorX.toFloat(), margin, pxValorX.toFloat(), height - margin, paintXLine)\\n            val paintTextX = Paint(paintText).apply { color = Color.parseColor(\\"#2563EB\\"); isFakeBoldText = true }\\n            canvas.drawText(\\"X\\", pxValorX.toFloat(), margin - 10f, paintTextX)\\n        }\\n\\n        return bitmap\\n    }\\n\\n    private fun desenharGraficoBarrasDiscreto(favoraveis: Double, total: Double, rotulo: String = \\"Sucessos\\"): Bitmap {\\n        val width = 900\\n        val height = 800\\n        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)\\n        val canvas = Canvas(bitmap)\\n        canvas.drawColor(Color.WHITE)\\n\\n        val margin = 80f\\n        val renderWidth = width - 2 * margin\\n        val renderHeight = height - 2 * margin\\n\\n        val paintAxis = Paint().apply { color = Color.parseColor(\\"#334155\\"); strokeWidth = 4f; isAntiAlias = true }\\n        val paintBar = Paint().apply { color = Color.parseColor(\\"#2563EB\\"); style = Paint.Style.FILL; isAntiAlias = true }\\n        val paintText = Paint().apply { color = Color.parseColor(\\"#475569\\"); textSize = 22f; isAntiAlias = true; textAlign = Paint.Align.CENTER }\\n\\n        canvas.drawLine(margin, height - margin, width - margin, height - margin, paintAxis)\\n        canvas.drawLine(margin, margin, margin, height - margin, paintAxis)\\n\\n        val barWidth = 160f\\n        val left = margin + 200f\\n        val barHeightRatio = if (total > 0) favoraveis / total else 0.0\\n        val top = (height - margin) - (barHeightRatio * renderHeight)\\n\\n        canvas.drawRect(left, top.toFloat(), left + barWidth, height - margin, paintBar)\\n\\n        val textoRotulo = if (total == 100.0) {\\n            String.format(\\"%s: %.2f%%\\", rotulo, favoraveis)\\n        } else {\\n            String.format(\\"%s: %.0f / %.0f\\", rotulo, favoraveis, total)\\n        }\\n        canvas.drawText(textoRotulo, left + barWidth / 2, top.toFloat() - 20f, paintText)\\n\\n        return bitmap\\n    }\\n}"}''';
  late final Map<String, dynamic> arquivosLogica;
  String telaAtual = "interface";
  
  final bool isOfflineMode = true;

  @override
  void initState() {
    super.initState();
    arquivosLogica = jsonDecode(rawJsonScripts);
    
    _controller = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setBackgroundColor(const Color(0x00000000))
      ..setNavigationDelegate(
        NavigationDelegate(
          onNavigationRequest: (NavigationRequest request) {
            if (request.url.endsWith('.html') || request.url.contains('file://')) {
              String nomeArquivo = request.url.split('/').last;
              rootBundle.loadString('assets/' + nomeArquivo).then((htmlConteudo) {
                  _controller.loadHtmlString(htmlConteudo, baseUrl: 'https://app.isaacx.com/');
                  telaAtual = nomeArquivo.replaceAll('.html', '');
              });
              return NavigationDecision.prevent; 
            }
            return NavigationDecision.navigate;
          },
        ),
      )
      ..addJavaScriptChannel(
        'IsaacBridge',
        onMessageReceived: (JavaScriptMessage message) async {
          final dadosRecebidos = message.message;
          print("DEBUG_MENSAGEM_RECEBIDA: $dadosRecebidos");

          try {
            final dadosJson = jsonDecode(dadosRecebidos);
            final String acaoSolicitada = dadosJson['acao'] ?? "padrao";
            final String valorDigitado = dadosJson['valor'] ?? "x";
            final String pacoteCompleto = acaoSolicitada + "|" + valorDigitado;

            if (isOfflineMode) {
                print("Rodando Kotlin Nativo Offline...");
                
            } else {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(
                    content: Text('⏳ Processando no Servidor...'),
                    backgroundColor: Colors.blueAccent,
                    duration: Duration(seconds: 2),
                  )
                );
                
                String coordenadaReal = "Localização pendente";
                try {
                  Position pos = await Geolocator.getCurrentPosition(desiredAccuracy: LocationAccuracy.high);
                  coordenadaReal = pos.latitude.toString() + ", " + pos.longitude.toString();
                } catch(e) {
                  print("Aviso: GPS não autorizado ou desligado.");
                }

                String scriptAlvo = arquivosLogica.containsKey(telaAtual + ".iscript") ? (telaAtual + ".iscript") : 
                                    (arquivosLogica.containsKey("logica.iscript") ? "logica.iscript" : (arquivosLogica.isNotEmpty ? arquivosLogica.keys.first : ""));

                final url = Uri.parse('https://isaac-studio-engine-94vf.onrender.com/api/v1/compilar');
                final response = await http.post(
                  url,
                  headers: {"Content-Type": "application/json"},
                  body: jsonEncode({
                    "projeto_nome": "AppAPK",
                    "arquivos": arquivosLogica,
                    "executar_ficheiro": scriptAlvo,
                    "input_digitado": pacoteCompleto,
                    "dados_hardware": {"gps": coordenadaReal}
                  }),
                );

                if (response.statusCode == 200) {
                  final dados = jsonDecode(response.body);
                  final linkGrafico = dados['link_grafico'];
                  final String logicaServidor = dados['resultado_terminal'] ?? "";

                      if(logicaServidor.contains("window.desenharRotaNoMapa")) {
                          RegExp exp = RegExp(r'window\.desenharRotaNoMapa\([^)]+\)');
                          var match = exp.firstMatch(logicaServidor);
                          if(match != null) {
                              _controller.runJavaScript(match.group(0)!);
                          }
                      }
                      
                      if (logicaServidor.contains("mudar_tela:")) {
                          RegExp exp = RegExp(r"mudar_tela:([a-zA-Z0-9_-]+)");
                          var match = exp.firstMatch(logicaServidor);
                          if (match != null) {
                              String novaTela = match.group(1)!;
                              telaAtual = novaTela; 
                              print("DEBUG_NAVEGACAO: $novaTela");
                              rootBundle.loadString('assets/' + novaTela + '.html').then((htmlConteudo) {
                                  _controller.loadHtmlString(htmlConteudo, baseUrl: 'https://app.isaacx.com/');

                              }).catchError((e) {
                                  print("ERRO_NAVEGACAO: Arquivo 'assets/$novaTela.html' nao encontrado!");
                              });
                          }
                      }
                      
                      if(logicaServidor.contains("abrir_link:")) {
                          RegExp exp = RegExp(r"abrir_link:(https?://[^\s]+)");
                          var match = exp.firstMatch(logicaServidor);
                          if(match != null) {
                              String urlUniversal = match.group(1)!;
                              launchUrl(Uri.parse(urlUniversal), mode: LaunchMode.externalApplication);
                          }
                      }
                  
                  if (logicaServidor.contains("instalar_pacote:")) {
                       RegExp exp = RegExp(r"instalar_pacote:([a-zA-Z0-9_.-]+)");
                       var match = exp.firstMatch(logicaServidor);
                       if (match != null) {
                            _instalarPacoteRemotamente(match.group(1)!);
                       }
                  }
                                                                             
                  if (linkGrafico != null && linkGrafico != 'Nenhum gráfico gerado') {
                     final timeStamp = DateTime.now().millisecondsSinceEpoch;
                     final urlSemCache = "$linkGrafico?t=$timeStamp";
                     
                     final scriptInjecao = '''
                        var urlImagem = "$urlSemCache";
                        var imgHtml = '<img src="' + urlImagem + '" style="width:100%; height:100%; min-height:200px; object-fit:contain; border-radius:8px;" />';
                        var area = document.getElementById('area_grafico');
                        
                        if(area) {
                          area.innerHTML = imgHtml;
                        } else {
                          var fallback = document.createElement('div');
                          fallback.style.cssText = "background-color: #000000; width: 100%; height: 250px; border-radius: 8px; display: flex; justify-content: center; align-items: center; margin-top: 20px; border: 2px solid red;";
                          fallback.innerHTML = imgHtml;
                          document.body.appendChild(fallback);
                        }
                     ''';
                     _controller.runJavaScript(scriptInjecao);
                     
                     ScaffoldMessenger.of(context).showSnackBar(
                        const SnackBar(content: Text('📊 Gráfico renderizado!'), backgroundColor: Colors.green),
                      );
                  } 
                  
                } else {
                  throw Exception('HTTP ${response.statusCode}');
                }
            } 

          } catch (e) {
             print("ERRO_GERACAO: $e");
             ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text('❌ Erro: $e'), backgroundColor: Colors.red),
              );
              
             if (e.toString().contains("SocketException") || e.toString().contains("ClientException")) {
                 final scriptOffline = '''
                    document.body.innerHTML = "<div style='font-family:sans-serif; text-align:center; padding:50px; background:#1A2235; color:white; height:100vh; display:flex; flex-direction:column; justify-content:center;'><h2>Sem Conexão</h2><p>Você está offline. Algumas functions em nuvem foram pausadas.</p><button onclick='window.location.reload()' style='padding:15px; border-radius:8px; background:#00E676; border:none; font-weight:bold; margin-top:20px;'>TENTAR RECONECTAR</button></div>";
                 ''';
                 _controller.runJavaScript(scriptOffline);
             }
          }
        },
      );
      
    _carregarInterface();
  }

  Future<void> _carregarInterface() async {
  final String htmlContent = await rootBundle.loadString('assets/interface.html');
  await _controller.loadHtmlString(htmlContent, baseUrl: 'https://app.isaacx.com/');
          
    bool servicoHabilitado = await Geolocator.isLocationServiceEnabled();
    LocationPermission permissao = await Geolocator.checkPermission();
    if (permissao == LocationPermission.denied) {
      permissao = await Geolocator.requestPermission();
    }
    
    if (servicoHabilitado && (permissao == LocationPermission.always || permissao == LocationPermission.whileInUse)) {
      Geolocator.getPositionStream(
        locationSettings: const LocationSettings(accuracy: LocationAccuracy.high, distanceFilter: 2)
      ).listen((Position pos) {
         _controller.runJavaScript("if(typeof window.atualizarGPSNativo === 'function') { window.atualizarGPSNativo(${pos.latitude}, ${pos.longitude}); }");
      });
    }
  }

  Future<void> _instalarPacoteRemotamente(String pacote) async {
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('📦 Baixando dependência automática: $pacote...'), backgroundColor: Colors.blueAccent, duration: const Duration(seconds: 4)));
    try {
      final urlStr = isOfflineMode ? 'http://127.0.0.1:8000/api/v1/pip' : 'https://isaac-studio-engine-94vf.onrender.com/api/v1/pip';
      final response = await http.post(
        Uri.parse(urlStr),
        headers: {"Content-Type": "application/json", "X-API-Key": "admin_master_bypass_token"},
        body: jsonEncode({"pacote": pacote}),
      );
      if (response.statusCode == 200) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('✅ $pacote instalado! Tente a ação novamente.'), backgroundColor: Colors.green));
      else throw Exception("Erro no servidor ao baixar o pacote.");
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('❌ Falha ao instalar $pacote'), backgroundColor: Colors.red));
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: SafeArea(
        child: WebViewWidget(controller: _controller),
      ),
    );
  }
}
